const e="한국 애니메이션·게임 더빙 전문 성우의 녹음실 연기. 발음이 또박또박 맑고, 목소리에 울림과 힘이 있으며, 캐릭터가 분명하다. 문장 중간에 일부러 끊거나 뜸을 들이지 않고 한 호흡으로 이어 읽는다. 연극 배우나 일상 대화 말투가 아니다.",a="전장에서 수백 군사에게 외치는 함성. 흥분하고 격앙되어 가슴에서 터져 나오는 큰 소리. 가성이 아니다.",o="어여쁜 여인.",r="여성성을 살린 곱고 맑은 여자 목소리. 남자처럼 낮게 깔거나 굵게 내지 않는다.",t={"mh-soseono":{voice:"Kore",style:"나라를 세운 우아한 왕비. 따뜻한 위엄과 여유, 품위 있고 차분하다. 거만하거나 차갑지 않다.",tap:["말씀하소서.","부르셨사옵니까.","곁에 있사옵니다. 하명하소서."],obey:["그리하겠사옵니다. 염려 마소서.","맡겨 주소서. 차질 없이 해내겠사옵니다.","뜻을 받들겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다! 지켜보소서!","흔들리지 마라! 우리가 세울 나라다!","백성의 땅을 지킨다! 나아가라!","이겼사옵니다. 다친 이부터 살피소서.","송구하옵니다. 다시 일어서면 되옵니다."],art:["shout","두려워 마라! 이 땅은 우리가 지킨다! 함성을 올려라!"],recorded:!0},"miri-ruler":{voice:"Achernar",style:"서른 중반의 넉넉한 곳간지기. 볼이 올라가게 푸근하고 환하게 활짝 웃으며 말한다. 정직하고 부지런하다.",tap:["<laugh> 예, 밭에서 왔사옵니다.","부르셨사옵니까.","곳간은 든든하옵니다."],obey:["씨 뿌린 대로 거두옵니다.","부지런히 해 두겠사옵니다.","맡겨 주시면 가득 채우겠사옵니다."],auto:["배불리 먹은 군사는 지지 않사옵니다!","곳간을 지켜라! 한 톨도 내주지 마라!","힘껏 밀어라! 가을이 기다린다!","<laugh> 씨 뿌린 대로 거두었사옵니다.","흉년도 넘기면 그만이옵니다."],art:["shout","배부른 군사가 이긴다! 함성을 올려라!"],recorded:!0},"daegaya-1":{voice:"Nika",style:"서른의 당찬 대장장이 여장부. 맑고 힘 있는 여기사 목소리로 시원시원하며, 가끔 입꼬리만 올려 씩 웃는다.",tap:["망치 내려놓고 왔사옵니다.","무엇을 벼리오리까.","<laugh> 쇠는 달궈 두었사옵니다."],obey:["단단히 벼려 보이겠사옵니다.","가야 쇠는 꺾이지 않사옵니다.","두들겨서라도 해내겠사옵니다."],auto:["가야 쇠맛을 보여 주겠사옵니다!","앞으로! 쇠는 달궈졌을 때 친다!","방패째 쪼개 버려라!","단단히 벼린 보람이 있사옵니다.","날이 무뎠사옵니다. 다시 벼리겠사옵니다."],art:["vanguard","내가 앞장선다! 가야 쇠로 길을 뚫어라!"],recorded:!0},"guya-3":{voice:"Leda",style:"스물일곱의 젊은 여장수. 단정하고 결연하며, 맑고 힘 있는 여기사 목소리로 또렷하게 말한다. 늙거나 지친 기색이 없다.",tap:["여기 있사옵니다.","부르셨사옵니까.","분부를 기다리고 있었사옵니다."],obey:["분부 받들겠사옵니다.","반드시 완수하겠사옵니다.","목숨을 걸고 임무를 다하겠사옵니다."],auto:["이 싸움, 제가 맡겠사옵니다!","한 치도 물러서지 않겠사옵니다!","반드시 이기고 돌아오겠사옵니다!","적을 물리쳤사옵니다!","송구하옵니다. 다시 한번 기회를 주시옵소서."],art:["vanguard","나를 따르라!"],recorded:!0},"anya-1":{voice:"Autonoe",style:"스물둘의 차고 날카로운 칼잡이. 짧은 말을 담백하게, 맑고 서늘한 여인의 목소리로. 서늘한 매력이 있다.",tap:["예. 듣고 있사옵니다.","칼은 뽑혀 있사옵니다.","말씀하시옵소서."],obey:["받들겠사옵니다. 바꾸지 않사옵니다.","정한 대로 하겠사옵니다.","베고 오겠사옵니다."],auto:["이 칼이 맡겠사옵니다!","숨죽여라. 칼끝이 닿을 때까지!","한 놈도 놓치지 마라!","끝났사옵니다. 칼을 거두겠사옵니다.","물러나옵니다. 뜻은 꺾이지 않았사옵니다."],art:["ambush","숨어 있던 칼을 뽑아라! 지금 베어라!"],recorded:!0},"bukokjeo-1":{voice:"Jori",style:"서른 후반의 굳센 여인. 말수가 적고 단단하며, 고향을 그리는 정이 은근히 묻어난다.",tap:["예, 여기 있사옵니다.","바다는 잔잔하옵니다.","무슨 일이시옵니까."],obey:["물길은 제가 열겠사옵니다.","알겠사옵니다. 다녀오겠사옵니다.","얼음 바다보다야 쉽사옵니다."],auto:["작살은 빗나가지 않사옵니다!","물속에서 치고 올라라!","놓치지 마라! 줄을 당겨라!","잡았사옵니다. 큰 놈이었사옵니다.","물살이 셌사옵니다. 다시 나가겠사옵니다."],art:["ambush","물밑에 숨은 자들아, 솟구쳐 작살을 꽂아라!"],recorded:!0},"jm-okjeo-1":{voice:"Tova",style:"서른 후반의 믿음직한 여인. 우직하되 고향 이야기엔 정이 묻어난다.",tap:["노 잡고 있사옵니다.","찬 바닷바람이 좋사옵니다.","여기 있사옵니다."],obey:["뱃머리는 맡겨 주시옵소서.","노 저어 다녀오겠사옵니다.","든든히 해 두겠사옵니다."],auto:["고향 바다에서 질 수는 없사옵니다!","배를 붙여라! 뛰어올라라!","파도 뒤에 숨어서 쳐라!","물길이 우리 편이었사옵니다.","파도가 높았사옵니다. 송구하옵니다."],art:["ambush","파도 밑에서 일어나라! 배째 뒤집어라!"],recorded:!0},"hwanna-2":{voice:"Despina",style:"스물여섯의 명궁. 여유롭고 자신만만하며, 눈웃음치듯 입꼬리를 올린 요염한 웃음이 묻어난다.",tap:["겨눌 곳이 있사옵니까.","활은 늘 당겨 두옵니다.","<laugh> 어머, 부르셨사옵니까."],obey:["단숨에 꿰뚫어 드리겠사옵니다.","웃으며 다녀오겠사옵니다.","버들처럼 휘었다 놓겠사옵니다."],auto:["제 화살 끝을 지켜보시옵소서!","시위를 당겨라! 숨을 멈춰라!","쏘아라! 한 발에 하나씩!","<laugh> 빗나간 화살은 없었사옵니다.","바람이 심술을 부렸사옵니다."],art:["snipe","버들처럼 휘었다가, 단숨에 꿰뚫는다!"],recorded:!0},"sangdang-2":{voice:"Erinome",style:"스물여덟의 화끈한 대장장이. 맑고 시원하게 내지르며 우직하고 쾌활하다. 어려 보이는 얼굴로 씨익 웃으며 말한다.",tap:["<laugh> 부르셨사옵니까!","쇠 식기 전에 말씀하소서.","풀무 곁에 있사옵니다."],obey:["단단히 달궈 보겠사옵니다!","시원하게 해치우겠사옵니다!","두들기면 다 되옵니다!"],auto:["싸움도 쇠처럼 달구겠사옵니다!","두들겨라! 식기 전에 쳐라!","메를 들어라! 밀어붙여라!","<laugh> 시원하게 두들겼사옵니다!","불이 약했사옵니다. 다시 달구겠사옵니다."],art:["vanguard","내가 앞장선다! 메를 들고 돌격하라!"],recorded:!0},"gampyeong-1":{voice:"Callirrhoe",style:"서른하나의 배짱 좋은 뱃사람 선장. 시원시원하고 장난기 있게 툭툭 던지며, 웃음기 어린 자신만만한 목소리. 늙거나 쉰 목소리가 아니다.",tap:["물때 맞춰 왔사옵니다.","<laugh> 또 무슨 일이옵니까, 주군.","배는 언제든 띄울 수 있사옵니다."],obey:["맡겨 두시옵소서. 바람은 제 편이옵니다.","물길은 제가 열겠사옵니다.","걱정 붙들어 매시옵소서."],auto:["제 삿대 맛을 보여 드리겠사옵니다!","노를 저어라! 꾸물대지 마라!","갈대숲에 배를 숨겨라!","<laugh> 그것 보시옵소서. 제 말이 맞았사옵니다.","물때를 잘못 읽었사옵니다. 다음엔 놓치지 않겠사옵니다."],art:["ambush","갈대숲의 배들아, 나와라! 뱃전을 들이받아라!"],recorded:!0},"dongokjeo-ruler":{voice:"Despina",style:"서른넷의 깐깐하고 매혹적인 소금 상단 여주인. 서늘하고 또렷하게, 값을 따지듯 야무지게 말하며 입가엔 여유로운 미소. 늙거나 쉰 목소리가 아니다.",tap:["값은 값대로이옵니다.","소금 셈 중이었사옵니다.","무슨 거래이시옵니까."],obey:["값은 값대로 받아 오겠사옵니다.","손해 볼 일은 없사옵니다.","셈은 이미 끝났사옵니다."],auto:["이 싸움, 남는 장사로 만들겠사옵니다!","물러나는 척해라! 끌어들여라!","서두르지 마라! 값은 저들이 치른다!","값은 값대로 받아 냈사옵니다.","밑진 장사였사옵니다. 되갚겠사옵니다."],art:["feint","물러나라! 미끼를 물면 그때 값을 받는다!"],recorded:!0},"mh-mahan-2":{voice:"Laomedeia",style:"스물여덟의 산성 문지기. 차분하고 굳으며 믿음직하다. 입을 다문 채 엷게 미소 짓는 듯한 고른 목소리.",tap:["성문은 닫혀 있사옵니다.","창 들고 왔사옵니다.","예, 곁에 있사옵니다."],obey:["끝까지 지켜 내겠사옵니다.","성문처럼 굳게 받들겠사옵니다.","믿고 맡기시옵소서."],auto:["이 성문은 넘지 못하옵니다!","산길에 숨어 기다려라!","자리를 지켜라! 흔들리지 마라!","<laugh> 성문은 굳건하옵니다.","면목 없사옵니다. 창을 다시 세우겠사옵니다."],art:["ambush","산성 위에서 내리쳐라! 한 놈도 못 오른다!"],recorded:!0},"sr-yangsan-1":{voice:"Leda",style:"열아홉의 명랑한 물가 사냥꾼. 밝고 재빠르며 생기 있게 통통 튄다. 천진하게 활짝 웃으며 말한다.",tap:["<laugh> 물새 왔사옵니다!","헤엄치다 왔사옵니다!","무엇이든 시키시옵소서!"],obey:["물새처럼 다녀오겠사옵니다!","금방 해내겠사옵니다!","알천 물길로 가겠사옵니다!"],auto:["소녀가 물길로 앞서겠사옵니다!","물속으로 숨어라! 소리 내지 마라!","지금이다! 물 밖으로 뛰어라!","<laugh> 이겼사옵니다! 물새가 해냈사옵니다!","흑, 물에 빠졌사옵니다. 다시 하겠사옵니다!"],art:["ambush","물새처럼 날아올라라! 물가에서 덮쳐라!"],recorded:!0},"wander-04":{voice:"Lora",style:"스물여섯의 차가운 자객. 감정 없이 짧게, 속삭이듯 서늘한 매혹이 있는 여인의 목소리.",tap:["듣고 있사옵니다.","소리 없이 왔사옵니다.","누구를 치오리까."],obey:["뜻이 맞으니 하겠사옵니다.","흔적은 남기지 않사옵니다.","셈은 끝났사옵니다. 가겠사옵니다."],auto:["소리 없이 끝내겠사옵니다!","불을 꺼라. 어둠이 우리 편이다!","뒤를 잡아라! 목을 노려라!","끝났사옵니다. 흔적은 없사옵니다.","셈이 틀렸사옵니다. 물러나겠사옵니다."],art:["ambush","어둠에서 일어나라! 소리 없이 목을 베어라!"],recorded:!0},"bullae-ruler":{voice:"Lumi",style:"스물여덟의 묵묵한 활잡이. 잔잔하고 고른 맑은 목소리, 말수가 적고 한결같다. 은은한 미소가 비친다.",tap:["예. 곁에 있사옵니다.","활은 휘지 않사옵니다.","하명하시옵소서."],obey:["박달 활처럼 곧게 하겠사옵니다.","지키겠사옵니다.","말없이 해 두겠사옵니다."],auto:["박달나무 활이 맡겠사옵니다!","시위를 메겨라! 기다려라!","쏘아라! 흔들리지 마라!","<laugh> 곧게 날아갔사옵니다.","빗나갔사옵니다. 다시 겨누겠사옵니다."],art:["snipe","박달 활은 휘지 않는다! 이 한 발로 끝낸다!"],recorded:!0},"wander-06":{voice:"Nika",style:"열아홉의 산 사냥꾼. 낯을 가려 짧게 말하며, 시린 새벽 공기처럼 서늘하고 맑다.",tap:["고개에서 왔사옵니다.","부르셨사옵니까.","눈 위에서 왔사옵니다."],obey:["먼저 밟고 오겠사옵니다.","뒤따르시옵소서.","끝까지 쫓겠사옵니다."],auto:["안개 낀 고개는 소녀가 맡겠사옵니다!","안개 속에 숨어라! 숨소리도 죽여라!","지금 덮쳐라! 고개 위에서!","산이 우리 편이었사옵니다.","놓쳤사옵니다. 발자국은 남았사옵니다."],art:["ambush","안개 속에서 일어나라! 고개 아래로 몰아쳐라!"],recorded:!0},"gwanna-2":{voice:"Nyla",style:"스물일곱의 엄격한 무장. 군인답게 단정하고 빈틈없이, 맑고 곧은 여인의 목소리로 말한다.",tap:["대령하였사옵니다.","명을 기다리옵니다.","빈틈은 없사옵니다."],obey:["빈틈없이 받들겠사옵니다.","즉시 시행하겠사옵니다.","한 치 어긋남 없이 하겠사옵니다."],auto:["제가 선봉에 서겠사옵니다!","대오를 맞춰라! 창을 세워라!","겨눈 곳만 찔러라! 앞으로!","빈틈없이 끝냈사옵니다.","빈틈을 보였사옵니다. 벌을 받겠사옵니다."],art:["vanguard","창을 세워라! 내 뒤를 따라 단숨에 찔러라!"],recorded:!0},"balla-1":{voice:"Rina",style:"스물넷의 옹관 무덤지기. 세고 맑게 내리꽂는 무당의 기운, 흔들림 없고 서늘하게 요염하다.",tap:["조상들께서 이르시기를.","거울이 울렸사옵니다.","옹관 곁에서 왔사옵니다."],obey:["조상들께서 허락하셨사옵니다.","받들겠사옵니다. 길은 열렸사옵니다.","죽은 이들도 거들 것이옵니다."],auto:["조상들께서 이 싸움을 맡기셨사옵니다!","물길을 따라 숨어라! 넋이 지켜 준다!","쳐라! 조상들이 보고 계신다!","조상들께서 기뻐하시옵니다.","조상들께서 아직이라 하시옵니다."],art:["ambush","잠든 조상이여, 일어나소서! 물길에서 쳐라!"],recorded:!0},"iseo-1":{voice:"Sola",style:"스물의 씩씩한 왈가닥 장수. 당차고 허세 섞인 힘찬 목소리, 내가 최고라는 듯 자신만만하게 웃으며 말한다.",tap:["저 여기 있사옵니다!","<laugh> 고개쯤이야 거뜬하옵니다!","싸울 일이옵니까!"],obey:["맡겨 주시옵소서!","제가 먼저 넘겠사옵니다!","거뜬히 해내겠사옵니다!"],auto:["이 싸움, 맡겨 주시옵소서!","고개 너머로 숨어라! 내 신호에 뛰어라!","따라와라! 고개는 내가 넘는다!","<laugh> 보셨사옵니까! 거뜬했사옵니다!","으윽, 이번 고개는 높았사옵니다!"],art:["ambush","고개 위에서 뛰어내려라! 내가 맨 먼저다!"],recorded:!0},"jomun-ruler":{voice:"Sulafat",style:"스물다섯의 매서운 산길잡이. 짧고 담백하게 말하며 감정을 감추고, 칼날 같은 서늘한 매력이 있다.",tap:["예. 말씀하시옵소서.","산길은 살펴 두었사옵니다.","경계 중이옵니다."],obey:["따르겠사옵니다. 끝까지.","산길은 저만 아옵니다.","곧 다녀오겠사옵니다."],auto:["길 잃을 일은 없사옵니다!","산길에 숨어라. 기다려라!","골짜기를 막아라! 퇴로를 끊어라!","끝났사옵니다. 길은 지켰사옵니다.","물러나옵니다. 이 빚은 갚겠사옵니다."],art:["ambush","숨은 길로 돌아 들어라! 뒤를 끊어라!"],recorded:!0},"wander-09":{voice:"Tari",style:"스물일곱의 고귀한 신지. 하늘하늘 기품 있고 차분하며, 어깨 너머로 돌아보듯 속 깊은 은근한 매혹이 있다.",tap:["별을 살피던 참이옵니다.","살펴보니 때가 왔사옵니다.","하문하시옵소서."],obey:["세 번 살피고 움직이겠사옵니다.","살펴보니 옳은 뜻이옵니다.","그리하겠사옵니다."],auto:["살펴보니, 이길 싸움이옵니다!","대열을 고요히 지켜라!","서두르지 마라! 적을 깊이 끌어들여라!","별자리대로 되었사옵니다.","살핌이 모자랐사옵니다. 송구하옵니다."],art:["feint","물러나는 척하라! 별이 뜨면 돌아서 쳐라!"],recorded:!0},"eumjeup-1":{voice:"Tova",style:"서른넷의 호기로운 칼잡이. 힘 있고 끈질기며, 한쪽 입꼬리를 올려 코웃음 치듯 자신만만하게 웃는다.",tap:["쏠 곳이 있사옵니까.","칼은 날이 서 있사옵니다.","<laugh> 흥, 부르셨사옵니까."],obey:["끝까지 따라붙겠사옵니다.","한번 문 것은 놓지 않사옵니다.","물고 늘어지겠사옵니다."],auto:["벌처럼 쏘고 끝까지 쫓겠사옵니다!","물고 늘어져라! 놓치지 마라!","쏘아붙여라! 쉴 틈을 주지 마라!","<laugh> 끝까지 쫓아 잡았사옵니다.","놓쳤사옵니다. 하지만 또 쫓겠사옵니다."],art:["vanguard","벌 떼처럼 덤벼라! 내가 앞장선다!"],recorded:!0},"jeoga-1":{voice:"Veda",style:"서른셋의 과묵한 창잡이. 날 서고 사나운 여전사, 맑고 힘 있는 목소리로 짧게 말한다.",tap:["예, 왔사옵니다.","창 들었사옵니다.","누구를 찌르오리까."],obey:["찌르고 오겠사옵니다.","먼저 찾겠사옵니다.","알겠사옵니다."],auto:["어둠에서 찌르겠사옵니다!","불 끄고 기다려라!","찔러라! 그리고 사라져라!","다 찔렀사옵니다.","물렸사옵니다. 다시 찌르겠사옵니다."],art:["ambush","어둠에서 찔러라! 어둠으로 사라져라!"],recorded:!0},"anya-2":{voice:"Zuri",style:"스물의 영민한 활잡이. 조용하고 침착하며 맑게 속삭이듯 말한다. 웃을 땐 소리 죽여 살짝 웃는다.",tap:["쉿, 여기 있사옵니다.","발소리는 없었사옵니다.","살펴 두었사옵니다."],obey:["쉿, 조용히 다녀오겠사옵니다.","소리 없이 살피겠사옵니다.","밤길은 소녀가 맡겠사옵니다."],auto:["쉿! 소녀가 먼저 살피겠사옵니다!","숨죽여라! 발소리를 죽여라!","어둠을 타고 둘러싸라!","<laugh> 쉿, 다 끝났사옵니다.","들켰사옵니다. 다음엔 숨기겠사옵니다."],art:["ambush","쉿, 숨어라! 지금이다, 한꺼번에 쏘아라!"],recorded:!0},"wander-18":{voice:"Despina",style:"스물넷의 영리하고 매혹적인 신지. 나긋하고 달콤하게 뼈 있는 농을 던지며, 속을 감춘 채 입가에만 살짝 미소를 머금고 말한다.",tap:["<laugh> 부르셨사옵니까.","이기는 쪽 곁이옵니다.","무슨 꾀가 필요하시옵니까?"],obey:["이기실 일이니 따르겠사옵니다.","좋은 수이옵니다, 그렇지 않사옵니까?","곱게 다녀오겠사옵니다."],auto:["이길 싸움이니 제가 맡겠사옵니다!","흔들리는 놈부터 꾀어내라!","이기는 쪽에 붙으라 외쳐라!","<laugh> 이기는 쪽에 서길 잘했사옵니다.","지는 쪽은 싫사옵니다. 다시 이기시옵소서."],art:["sway","무기를 버려라! 이기는 쪽으로 오면 살려 준다!"],recorded:!0},"miri-2":{voice:"Achernar",style:"스물의 앳되고 다정한 젊은 무당. 수줍고 순하며, 입가에만 살포시 미소를 머금고 부드럽게 말한다.",tap:["방울이 울렸사옵니다.","<laugh> 부르셨사옵니까.","하늘 뜻을 여쭈오리까."],obey:["하늘이 그리하라 하시옵니다.","방울 따라 다녀오겠사옵니다.","기꺼이 받들겠사옵니다."],auto:["하늘이 이 싸움을 지켜 주신다 하시옵니다!","방울 소리를 따라 나아가라!","두려워 마라! 하늘이 보고 계신다!","<laugh> 하늘이 웃으셨사옵니다.","하늘이 아직 때가 아니라 하시옵니다."],art:["rite","방울아 울려라! 하늘이여, 우리 군사를 지키소서!"],recorded:!0},"wander-02":{voice:"Laomedeia",style:"스물하나의 쾌활한 명궁. 시원시원하고 자신만만하며, 한쪽 눈을 찡긋하고 입을 크게 벌려 밝게 웃으며 말한다.",tap:["<laugh> 부르셨사옵니까!","어디를 쏘아 드리오리까.","값은 넉넉하시옵니까?"],obey:["값만큼 꽂아 드리겠사옵니다!","꽃 이름이라 얕보지 마시옵소서.","한 발이면 넉넉하옵니다."],auto:["이 싸움, 제 활로 값을 하겠사옵니다!","시위를 당겨라! 미간을 노려라!","쏘아라! 꽃잎처럼 쏟아부어라!","<laugh> 한 발도 헛되이 안 쐈사옵니다!","이번 값은 덜 받겠사옵니다."],art:["snipe","얕보지 마라! 이 한 발이 적장의 미간에 꽂힌다!"],recorded:!0},"wander-20":{voice:"Sola",style:"스물다섯의 호탕한 창잡이. 시원시원하고 실속 있으며, 입을 활짝 벌려 크게 웃으며 거침없이 말한다.",tap:["<laugh> 왔사옵니다!","흥정할 일이옵니까?","밤 장터에서 왔사옵니다."],obey:["웃으며 해치우겠사옵니다!","실속 있게 해 오겠사옵니다.","제 몫만 잊지 마시옵소서."],auto:["웃으며 찌르는 맛을 보여 드리겠사옵니다!","밤길로 돌아라! 창끝을 숨겨라!","지금이다! 옆구리를 찔러라!","<laugh> 웃으며 이겼사옵니다!","밑졌사옵니다. 웃으며 되찾겠사옵니다."],art:["ambush","밤길로 숨어들어라! 웃으며 옆구리를 찔러라!"],recorded:!0},"wander-15":{voice:"Nika",style:"스물넷의 넉살 좋은 대장장이 처녀. 흥 많고 싹싹하며, 어려 보이는 얼굴로 살짝 입을 벌려 해맑게 웃으며 말한다.",tap:["한 잔 하시겠사옵니까?","<laugh> 일하다 왔사옵니다!","노래 한 자락 하오리까?"],obey:["부지런히 해 두겠사옵니다!","끝나면 한 잔이옵니다!","흥겹게 해치우겠사옵니다."],auto:["노래 부르며 이기겠사옵니다!","장단 맞춰 밀어라! 신명 나게 쳐라!","흥을 올려라! 소리를 질러라!","<laugh> 오늘 밤은 잔치이옵니다!","첫 잔은 쓴 법이옵니다. 다시 하겠사옵니다."],art:["shout","노래하라! 북을 울려라! 이긴 뒤엔 잔치다!"],recorded:!0},"wander-03":{voice:"Autonoe",style:"스물둘의 사랑스러운 춤꾼. 애교 있고 나긋하며 말끝을 살짝 늘이고, 아이돌처럼 화사하게 입꼬리를 올려 웃으며 말한다.",tap:["<laugh> 부르셨사옵니까?","춤추다 왔사옵니다.","소녀, 여기 있사옵니다."],obey:["사르르 녹여 드리겠사옵니다.","춤추듯 다녀오겠사옵니다.","말 한마디로 열어 보이겠사옵니다."],auto:["소녀가 사르르 열어 보이겠사옵니다!","노래로 흔들어라! 마음을 꺾어라!","부드럽게 감싸라! 놓치지 마라!","<laugh> 사르르 녹았사옵니다.","마음이 굳은 적이었사옵니다."],art:["sway","칼을 내려놓아라! 웃으며 이리로 넘어오너라!"],recorded:!0},"wander-13":{voice:"Erinome",style:"스물둘의 능청스러운 잔치 염탐꾼. 눈치 빠르고 약삭빠르며, 곁눈질하듯 자신감 있게 입꼬리만 살짝 올려 웃으며 말한다.",tap:["들은 말이 있사옵니다.","<laugh> 잔치에서 왔사옵니다.","누구 속을 캐 오리까."],obey:["들은 말대로 하겠사옵니다.","위태로우면 먼저 빠지겠사옵니다.","술잔 들고 다녀오겠사옵니다."],auto:["적진 속은 다 캐 두었사옵니다!","잔치 틈에 숨어들어라!","뒤를 쳐라! 술 취한 놈부터!","<laugh> 들은 말대로였사옵니다.","먼저 빠졌사옵니다. 들은 말과 달랐사옵니다."],art:["ambush","잔칫상 밑에서 칼을 뽑아라! 취한 틈을 쳐라!"],recorded:!0},"goja-2":{voice:"Leda",style:"스물의 앳되고 귀여운 아가씨. 천진하고 씩씩하며 복스럽고, 귀엽게 씨익 웃으며 밝게 말한다.",tap:["<laugh> 진주 건져 왔사옵니다!","부르셨사옵니까!","복 가져왔사옵니다!"],obey:["씩씩하게 다녀오겠사옵니다!","숨 한 번에 해내겠사옵니다!","복은 덤으로 드리겠사옵니다."],auto:["소녀가 복을 몰고 오겠사옵니다!","숨 참고 기다려라! 물살을 타라!","덮쳐라! 그물로 감싸라!","<laugh> 복이 들어왔사옵니다!","물이 찼사옵니다. 다시 들어가겠사옵니다."],art:["sway","무기를 버려라! 복 받고 싶으면 이리 오너라!"],recorded:!0},"wander-01":{voice:"Sulafat",style:"서른셋의 원숙하고 요염한 여인. 느긋하고 다정하며 여유롭게, 요염하게 입꼬리만 올려 웃으며 말한다.",tap:["<laugh> 부르셨사옵니까.","살림 살피던 참이옵니다.","무슨 근심이시옵니까."],obey:["살아 보니 이리하는 게 옳사옵니다.","넉넉히 챙겨 오겠사옵니다.","염려 마시옵소서."],auto:["이 싸움은 제가 넉넉히 거두겠사옵니다!","든든히 먹고 버텨라! 곳간은 넉넉하다!","한 발도 물러서지 마라!","<laugh> 넉넉히 거두었사옵니다.","살아 보니 지는 날도 있사옵니다."],art:["shout","살아서 돌아가자! 다 함께 소리 높여라!"],recorded:!0},"wander-16":{voice:"Sola",style:"스물여섯의 당찬 대장장이 처녀. 맑고 힘 있는 여장부 목소리로 시원시원하고 솔직하며, 자신만만하게 씨익 웃으며 말한다.",tap:["메 들고 왔사옵니다.","<laugh> 두고 보시옵소서.","말보다 손이 빠르옵니다."],obey:["두고 보시옵소서. 해내겠사옵니다.","이 손으로 증명하겠사옵니다.","잘 드는 칼로 보이겠사옵니다."],auto:["잘 드는 칼맛을 보여 드리겠사옵니다!","칼을 고쳐 쥐어라! 밀어붙여라!","말은 필요 없다! 손으로 보여라!","<laugh> 두고 보시라 하였사옵니다!","쇠가 덜 달궈졌사옵니다. 다시 하겠사옵니다."],art:["shout","이 칼은 꺾이지 않는다! 소리 높여 밀어라!"],recorded:!0},"apdok-ruler":{voice:"Tari",style:"서른의 온화하고 기품 있는 고을 여주인. 차분하고 어질며, 화사하게 입꼬리를 올려 단아하게 미소 지으며 말한다.",tap:["논에서 왔사옵니다.","<laugh> 부르셨사옵니까.","벼는 잘 여물었사옵니다."],obey:["고을을 돌보듯 받들겠사옵니다.","차근차근 해 두겠사옵니다.","맡은 일은 끝까지 하겠사옵니다."],auto:["백성의 논두렁은 제가 지키겠사옵니다!","서두르지 마라! 차근차근 밀어라!","한 사람도 버리지 마라! 함께 가자!","<laugh> 백성이 배불리 먹겠사옵니다.","송구하옵니다. 다시 일구면 되옵니다."],art:["shout","이 들판은 우리 백성의 것이다! 함성을 올려라!"],recorded:!0},"michuhol-ruler":{voice:"Lumi",style:"서른하나의 호탕하고 매력 있는 상단 여주인. 시원시원하고 수완 좋으며, 모델처럼 자신 있게 씨익 웃으며 말한다.",tap:["<laugh> 부르셨사옵니까!","소금길에서 왔사옵니다.","무슨 장사이옵니까?"],obey:["남는 장사이옵니다. 하겠사옵니다.","곳간째 불려 오겠사옵니다.","의리로 받들겠사옵니다."],auto:["이 싸움도 남는 장사로 만들겠사옵니다!","물러나는 척하라! 미끼를 던져라!","서두르지 마라! 걸려들 때까지!","<laugh> 남는 장사였사옵니다!","밑진 셈이옵니다. 곱절로 받아 내겠사옵니다."],art:["feint","물러서는 척하라! 쫓아오면 그때 곱절로 받는다!"],recorded:!0},"us-2":{voice:"Zuri",style:"스물의 앳되고 활달한 처녀. 우직하고 신이 나 있으며, 이를 드러내고 밝게 활짝 웃으며 말한다.",tap:["<laugh> 노 젓다 왔사옵니다!","부르셨사옵니까!","배는 띄워 두었사옵니다."],obey:["신나게 다녀오겠사옵니다!","뱃길은 소녀가 이끌겠사옵니다.","물결 하나도 놓치지 않사옵니다."],auto:["이 물길은 소녀가 맡겠사옵니다!","물살을 타고 돌아 들어라!","지금이다! 뱃전에서 뛰어올라라!","<laugh> 신나게 이겼사옵니다!","물때를 놓쳤사옵니다. 다시 젓겠사옵니다."],art:["ambush","물살을 타고 숨어들어라! 옆에서 들이쳐라!"],recorded:!0},"golbeol-2":{voice:"Lora",style:"스물다섯이지만 어려 보이는 장난꾸러기. 날렵하고 능청스러우며 뻔뻔하게, 장난스레 씨익 웃으며 말한다.",tap:["<laugh> 갈대밭에서 왔사옵니다.","숨어 있었사옵니다.","누구를 골려 주오리까."],obey:["몰래 다녀오겠사옵니다.","숨을 곳은 다 아옵니다.","날쌔게 해치우겠사옵니다."],auto:["갈대밭이라면 소녀가 앞서겠사옵니다!","갈대 속에 엎드려라! 숨죽여라!","뒤로 돌아라! 발목을 베어라!","<laugh> 감쪽같이 해냈사옵니다.","꼬리를 밟혔사옵니다. 다시 숨겠사옵니다."],art:["ambush","갈대밭에서 일어나라! 뒤통수를 쳐라!"],recorded:!0},"samul-1":{voice:"Nika",style:"스물일곱이지만 어려 보이는 시원한 큰언니. 호쾌하고 정이 많으며 부지런하고, 씨익 웃으며 밝게 말한다.",tap:["<laugh> 노 놓고 왔사옵니다!","물소리가 좋사옵니다.","무슨 일이옵니까!"],obey:["뱃길은 제가 몰겠사옵니다!","후딱 다녀오겠사옵니다.","모두 데리고 가겠사옵니다."],auto:["물소리만 들어도 이길 길이 보이옵니다!","배를 숨겨라! 물굽이 뒤로!","노를 저어라! 한꺼번에 덮쳐라!","<laugh> 모두 무사히 돌아왔사옵니다.","물길을 잘못 읽었사옵니다. 송구하옵니다."],art:["ambush","물굽이 뒤에서 나와라! 뱃머리로 들이받아라!"],recorded:!0},"sabeol-1":{voice:"Leda",style:"열아홉의 장난기 많은 말괄량이. 들뜨고 성급하게 말이 빠르며, 어려 보이는 얼굴로 씨익 웃으며 말한다.",tap:["<laugh> 벌써 왔사옵니다!","앞자리는 제 몫이옵니다!","어디로 달리오리까!"],obey:["제일 먼저 다녀오겠사옵니다!","눈 깜짝할 새이옵니다!","고삐 잡고 달리겠사옵니다!"],auto:["앞자리는 제 몫이옵니다! 먼저 가겠사옵니다!","말을 몰아라! 물가로 돌아라!","뒤처지지 마라! 단숨에 덮쳐라!","<laugh> 제가 맨 먼저였사옵니다!","너무 서둘렀사옵니다. 다시 달리겠사옵니다!"],art:["ambush","물가로 돌아 달려라! 옆구리를 들이쳐라!"],recorded:!0},"usan-1":{voice:"Laomedeia",style:"스물여섯이지만 어려 보이는 쾌활한 섬 처녀. 대담하고 밝으며, 씨익 웃으며 시원하게 말한다.",tap:["<laugh> 섬에서 왔사옵니다!","작살 들고 왔사옵니다.","무엇을 잡아 오리까!"],obey:["바닷길은 제게 맡기시옵소서!","겁날 것 없사옵니다!","단숨에 다녀오겠사옵니다!"],auto:["이 싸움, 제가 앞장서겠사옵니다!","물속에 숨어라! 숨을 참아라!","작살을 던져라! 놓치지 마라!","<laugh> 큰 놈을 잡았사옵니다!","놓쳤사옵니다. 다음엔 꼭 잡겠사옵니다!"],art:["ambush","바위섬 뒤에서 뛰어들어라! 작살을 날려라!"],recorded:!0},"jomun-2":{voice:"Achernar",style:"스물셋의 살갑고 복스러운 누에치기 아가씨. 글래머러스한 매력에 다정하고 명랑하며, 볼이 발그레하게 눈과 입으로 함께 활짝 웃으며 말한다.",tap:["<laugh> 뽕밭에서 왔사옵니다.","부르셨사옵니까?","정성껏 모시겠사옵니다."],obey:["누에가 실 뽑듯 하겠사옵니다.","살뜰히 챙기겠사옵니다.","곱게 짜 올리겠사옵니다."],auto:["소녀가 실타래 풀듯 풀어 보겠사옵니다!","살살 달래라! 마음을 풀어라!","감싸 안아라! 하나도 놓치지 마라!","<laugh> 비단처럼 곱게 끝났사옵니다.","실이 엉켰사옵니다. 다시 풀겠사옵니다."],art:["sway","무기를 내려놓아라! 따뜻한 밥이 기다린다!"],recorded:!0},"uga-2":{voice:"Despina",style:"스물둘의 상냥하고 고운 아가씨. 푸근하고 부지런하며, 연예인처럼 화사하게 입가에 미소 지으며 말한다.",tap:["송아지 보다 왔사옵니다.","<laugh> 부르셨사옵니까.","들판은 푸르옵니다."],obey:["알맞은 때에 해 두겠사옵니다.","상냥히 다녀오겠사옵니다.","소처럼 꾸준히 하겠사옵니다."],auto:["든든한 들판처럼 버티겠사옵니다!","소처럼 우직하게 밀어라!","한 고랑씩 갈아엎어라!","<laugh> 풍년이옵니다!","송구하옵니다. 내년 봄을 기다리겠사옵니다."],art:["shout","소 떼처럼 밀고 나가라! 함성을 올려라!"],recorded:!0},"dongokjeo-2":{voice:"Sola",style:"서른의 호탕하고 겁 없는 여장부. 맑고 힘 있게 시원시원하며, 입을 크게 벌려 환하게 웃으며 말한다.",tap:["<laugh> 왔사옵니다!","짠바람이 좋사옵니다.","겁날 것 없사옵니다."],obey:["겁 없이 다녀오겠사옵니다!","억척같이 해내겠사옵니다.","소금 자루째 가져오겠사옵니다."],auto:["겁날 것 없사옵니다! 제가 앞서겠사옵니다!","바위 뒤에 숨어라! 기다려라!","지금이다! 한꺼번에 들이쳐라!","<laugh> 시원하게 이겼사옵니다!","짠물 좀 먹었사옵니다. 또 나가겠사옵니다."],art:["ambush","바위 뒤에서 뛰쳐나와라! 칼을 뽑아 들이쳐라!"],recorded:!0},"tamna-2":{voice:"Autonoe",style:"스물둘의 자유분방하고 정 많은 섬 처녀. 활달하고 밝으며, 어려 보이는 얼굴로 눈과 입으로 함께 씨익 웃으며 말한다.",tap:["<laugh> 말 타고 왔사옵니다!","오름에서 왔사옵니다.","부르셨사옵니까!"],obey:["소녀가 앞서겠사옵니다!","바람처럼 다녀오겠사옵니다!","산길이든 들길이든 가겠사옵니다."],auto:["오름이든 산길이든 소녀가 앞서겠사옵니다!","오름 뒤에 숨어라! 바람을 등져라!","말을 달려라! 내리닫아라!","<laugh> 바람이 우리 편이었사옵니다!","말이 지쳤사옵니다. 쉬고 다시 가겠사옵니다."],art:["ambush","오름 너머에서 내리달려라! 바람처럼 덮쳐라!"],recorded:!0},"ungcheon-1":{voice:"Erinome",style:"스물다섯이지만 어려 보이는 호탕한 여장사. 맑고 힘 있게 털털하며 장난기 많고, 눈과 입으로 함께 씨익 웃으며 말한다.",tap:["<laugh> 산에서 내려왔사옵니다!","몽둥이 들고 왔사옵니다.","누구를 혼내 주오리까!"],obey:["한달음에 다녀오겠사옵니다!","앞장은 제게 맡기시옵소서!","번쩍 들어 오겠사옵니다."],auto:["산에선 제가 제일 빠르옵니다!","산비탈에 엎드려라! 내 신호를 기다려라!","몽둥이를 휘둘러라! 쓸어버려라!","<laugh> 시원하게 혼내 주었사옵니다!","미끄러졌사옵니다. 다시 오르겠사옵니다!"],art:["ambush","산비탈에서 굴러 내려가라! 몽둥이로 쓸어버려라!"],recorded:!0},"tut-haebi":{voice:"Leda",style:"스물둘의 해맑고 씩씩한 아가씨. 밝고 쾌활하며 넉살 좋게, 이를 드러내고 활짝 웃으며 신나게 말하는 솜씨 좋은 쇠장이 처녀.",tap:["<laugh> 왔사옵니다!","품삯 이야기이옵니까?","쇠는 달궈 두었사옵니다."],obey:["품삯만큼 해내겠사옵니다!","맡겨 주시옵소서!","단단히 벼려 오겠사옵니다."],auto:["이 싸움, 품삯 몫은 하겠사옵니다!","도끼를 들어라! 힘껏 내리쳐라!","밀어붙여라! 쇠맛을 보여 줘라!","<laugh> 품삯 값은 했사옵니다!","품삯을 못 했사옵니다. 다시 하겠사옵니다."],art:["shout","도끼를 높이 들어라! 다 함께 소리쳐라!"],recorded:!0},"mh-jinwang":{voice:"Sulafat",style:"서른여덟의 우아하고 노련한 여왕. 품위 있고 느긋하며 속을 쉬이 드러내지 않고, 알 듯 모를 듯 엷게 미소 지으며 말한다. 거만하거나 차갑지 않다.",tap:["하명하소서.","<laugh> 사람을 살피던 참이옵니다.","곁에 있사옵니다."],obey:["그리하겠사옵니다.","사람 보는 눈은 녹슬지 않았사옵니다.","뜻대로 되게 하겠사옵니다."],auto:["이 싸움은 제가 거두겠사옵니다!","사람을 보고 움직여라! 서두르지 마라!","흔들리는 자부터 품어라!","<laugh> 보던 대로이옵니다.","잘못 보았사옵니다. 다시 살피겠사옵니다."],art:["sway","무기를 내려놓아라! 마한의 품으로 돌아오너라!"],recorded:!0},"jm-songbi":{voice:"Nika",style:"스물의 앳되고 사랑스러운 아가씨. 활달하고 자신만만하며 들뜨면 말이 빨라지고, 눈을 동그랗게 뜨고 환하게 미소 지으며 말한다.",tap:["<laugh> 활 들고 왔사옵니다!","겨눌 곳이 있사옵니까?","부르셨사옵니까!"],obey:["빗나가지 않게 하겠사옵니다!","단숨에 꿰뚫겠사옵니다!","겨눌 곳만 일러 주시옵소서!"],auto:["제 화살은 빗나가지 않사옵니다!","시위를 당겨라! 한꺼번에 쏘아라!","겨눈 곳만 쏘아라! 놓치지 마라!","<laugh> 보셨사옵니까! 다 맞혔사옵니다!","빗나갔사옵니다. 다시 겨누겠사옵니다!"],art:["snipe","빗나가지 않는다! 이 한 발로 적장을 꿰뚫는다!"],recorded:!0},"jm-haedal":{voice:"Lora",style:"스물여덟의 기품 있는 냉미인. 차분하고 자존심이 높으며 말을 아끼고, 맑고 서늘한 귀족 여인의 목소리로 담담하게 말한다.",tap:["활은 메어 두었사옵니다.","하명하시옵소서.","사냥터에서 왔사옵니다."],obey:["첫 살로 거두겠사옵니다.","말 대신 살로 보이겠사옵니다.","받들겠사옵니다."],auto:["부여의 첫 살은 제 몫이옵니다!","흰 깃 살을 메겨라! 겨누어라!","쏘아라! 한 살도 헛되이 말라!","첫 살에 거두었사옵니다.","살이 빗나갔사옵니다. 다시 겨누겠사옵니다."],art:["snipe","첫 살에 끝낸다! 적장의 숨통을 꿰뚫어라!"],recorded:!0},"jm-haengin-1":{voice:"Autonoe",style:"스물넷의 서늘한 미인. 과묵하고 경계심이 많으며, 달빛처럼 맑고 고요한 여인의 목소리로 담담하게 말한다.",tap:["산길에서 왔사옵니다.","달이 졌사옵니다.","말씀하시옵소서."],obey:["길은 제가 열겠사옵니다.","어둠을 타고 다녀오겠사옵니다.","발자국은 남기지 않사옵니다."],auto:["달 없는 밤은 제가 맡겠사옵니다!","불을 꺼라! 어둠에 숨어라!","지금이다! 산길에서 덮쳐라!","길은 열렸사옵니다.","들켰사옵니다. 다음 밤을 기다리겠사옵니다."],art:["ambush","달 없는 밤이다! 산길에서 일어나 덮쳐라!"],recorded:!0},"sr-aryeong":{voice:"Tari",style:"열아홉의 맑고 단아한 소녀. 어질고 신비로우며 하늘하늘 기품 있게, 입가에 맑은 미소를 머금고 들뜨지 않게 말한다.",tap:["<laugh> 부르셨사옵니까.","논에서 왔사옵니다.","백성은 배부르옵니다."],obey:["백성 먼저 살피겠사옵니다.","논밭을 돌보듯 하겠사옵니다.","정성껏 받들겠사옵니다."],auto:["백성의 논밭은 제가 지키겠사옵니다!","물러서지 마라! 논밭이 뒤에 있다!","함께 버텨라! 서로를 지켜라!","<laugh> 올해도 풍년이겠사옵니다.","송구하옵니다. 다시 씨를 뿌리겠사옵니다."],art:["shout","용이 지켜 준다! 다 함께 함성을 올려라!"],recorded:!0},"sr-danbi":{voice:"Leda",style:"열여덟의 앳되고 진지한 소녀. 충직하고 고집 있으며, 맑고 또렷한 목소리로 야무지게 말한다.",tap:["우물 곁에서 왔사옵니다.","활은 당겨 두었사옵니다.","명을 기다리옵니다."],obey:["목숨 걸고 지키겠사옵니다.","한 치도 물러서지 않겠사옵니다.","받들겠사옵니다."],auto:["소녀가 끝까지 지키겠사옵니다!","시위를 당겨라! 물러서지 마라!","우물을 지켜라! 쏘아라!","지켜 냈사옵니다.","송구하옵니다. 더 단단히 지키겠사옵니다."],art:["snipe","흔들리지 마라! 이 한 발로 우물을 지킨다!"],recorded:!0},"sr-goya-1":{voice:"Erinome",style:"스물다섯의 매혹적인 명사수. 여유롭고 장난기 많으며 능청스럽게, 화살 깃을 입술에 대듯 은근히 눈웃음치며 말한다.",tap:["<laugh> 부르셨사옵니까.","명활산에서 왔사옵니다.","바람은 제 편이옵니다."],obey:["웃으며 쏘고 오겠사옵니다.","바람도 비켜 갈 것이옵니다.","쓸모 있는 살이 되겠사옵니다."],auto:["쏘기 전에 한 번 웃겠사옵니다!","시위를 당겨라! 바람을 읽어라!","쏘아라! 웃으며 꿰뚫어라!","<laugh> 바람도 비켜 갔사옵니다.","살이 아까웠사옵니다. 다시 쏘겠사옵니다."],art:["snipe","명활산 바람도 비켜 간다! 이 한 발을 받아라!"],recorded:!0},"sr-jinji-1":{voice:"Sola",style:"스물넷의 거침없고 씩씩한 왈가닥 여전사. 맑고 힘 있는 여기사 목소리로 시원시원하며, 이를 드러내고 장난스럽게 씨익 웃으며 말한다.",tap:["<laugh> 범 잡다 왔사옵니다!","창 들고 왔사옵니다.","토함산에서 왔사옵니다!"],obey:["창부터 나가겠사옵니다!","앞길의 짐승은 치우겠사옵니다!","거침없이 해치우겠사옵니다!"],auto:["제 창이 먼저 나가겠사옵니다!","산비탈에 숨어라! 범처럼 기다려라!","덮쳐라! 범처럼 물어뜯어라!","<laugh> 범도 물러섰사옵니다!","으윽, 넘어졌사옵니다. 다시 찌르겠사옵니다!"],art:["ambush","토함산 범처럼 숨었다가 한꺼번에 덮쳐라!"],recorded:!0},"us-ruler":{voice:"Achernar",style:"스물의 다정하고 고운 아가씨. 온화하고 인정 많으며, 볼이 발그레하게 눈웃음 지으며 따스하게 말한다.",tap:["<laugh> 부르셨사옵니까.","제 백성은 무탈하옵니다.","곁에 있사옵니다."],obey:["제 백성을 위해 하겠사옵니다.","한결같이 받들겠사옵니다.","따스히 돌보겠사옵니다."],auto:["제 백성이 보고 있사옵니다!","마음을 열어라! 따스이 품어라!","서로 손을 잡아라! 놓지 마라!","<laugh> 모두 무사하옵니다.","송구하옵니다. 백성께 면목이 없사옵니다."],art:["sway","칼을 내려놓아라! 이 품으로 오면 모두 백성이다!"],recorded:!0},"saro-2":{voice:"Laomedeia",style:"스물둘의 상냥하고 명랑한 아가씨. 밝고 다정하며 솜씨 자랑을 살짝 하고, 볼이 붉게 물들도록 눈웃음 지으며 말한다.",tap:["<laugh> 노을이 고왔사옵니다.","해 질 녘이옵니다.","부르셨사옵니까!"],obey:["붉게 물들여 오겠사옵니다.","해 지기 전에 오겠사옵니다.","솜씨를 보여 드리겠사옵니다!"],auto:["해 질 녘 사냥은 제 몫이옵니다!","노을을 등져라! 시위를 당겨라!","쏘아라! 하늘을 붉게 물들여라!","<laugh> 노을처럼 곱게 끝났사옵니다.","해가 저물었사옵니다. 내일 또 쏘겠사옵니다."],art:["snipe","노을빛 화살이다! 한 발로 적장을 꿰뚫어라!"],recorded:!0},"gammun-2":{voice:"Despina",style:"스물여덟의 고혹적인 여인. 나른하고 신비로우며 꿈꾸듯 느긋하게, 눈을 내리깔고 요염하게 입꼬리를 올려 미소 지으며 말한다.",tap:["<laugh> 꿈을 꾸던 참이옵니다.","연기가 기울었사옵니다.","하늘이 부르셨사옵니다."],obey:["하늘 뜻이 그러하옵니다.","거울이 그리 비추옵니다.","꿈결처럼 다녀오겠사옵니다."],auto:["하늘이 이 싸움을 제게 맡기셨사옵니다!","방울을 흔들어라! 하늘을 불러라!","두려워 마라! 연기가 우리 쪽이다!","<laugh> 꿈에서 본 대로이옵니다.","연기가 흩어졌사옵니다. 다시 여쭙겠사옵니다."],art:["rite","거울아 빛나라! 하늘의 뜻이 우리 군사를 감싼다!"],recorded:!0},"mokji-ruler":{voice:"Veda",style:"서른일곱의 원숙하고 매력 있는 여인. 위엄 있고 노련하며 은근히 떠보듯, 짙은 눈매로 여유롭게 미소 지으며 말한다.",tap:["<laugh> 그릇을 재던 참이옵니다.","방울이 울렸사옵니다.","무슨 일이시옵니까."],obey:["그만한 뜻이시라면 따르겠사옵니다.","마한의 으뜸답게 하겠사옵니다.","그릇이 크시옵니다. 받들겠사옵니다."],auto:["마한의 으뜸이 이 싸움을 맡겠사옵니다!","흔들리는 자부터 꾀어라!","그릇이 작은 자는 넘어온다!","<laugh> 그만한 그릇이셨사옵니다.","제 눈이 흐렸사옵니다. 다시 재겠사옵니다."],art:["sway","마한의 방울이 부른다! 무기를 버리고 넘어오너라!"],recorded:!0},"mujin-ruler":{voice:"Jori",style:"쉰둘의 관록 있는 여장부. 고집 세고 든든하며 의젓하고, 맑고 힘 있는 원숙한 여인의 목소리로 차분히 말한다.",tap:["늙은이, 여기 있사옵니다.","산은 변함없사옵니다.","창 짚고 왔사옵니다."],obey:["늙은이가 보기에 옳사옵니다.","고집대로 해내겠사옵니다.","산처럼 버티겠사옵니다."],auto:["늙은이가 보기에 이길 싸움이옵니다!","산자락에 숨어라! 서두르지 마라!","산처럼 버텨라! 그리고 덮쳐라!","늙은이 말이 맞았사옵니다.","늙은 탓이옵니다. 다시 버티겠사옵니다."],art:["ambush","큰 산이 우리를 숨긴다! 산자락에서 덮쳐라!"],recorded:!0},"wansan-1":{voice:"Nyla",style:"스물넷의 침착한 미인. 정확하고 자신 있으며 말을 아끼고, 맑고 곧은 목소리로 입꼬리만 살짝 올려 미소 지으며 말한다.",tap:["예. 겨누고 있사옵니다.","한 발이면 되옵니다.","<laugh> 부르셨사옵니까."],obey:["단번에 쓰러뜨리겠사옵니다.","정확히 해 두겠사옵니다.","겨눈 대로 하겠사옵니다."],auto:["한 발이면 되옵니다! 제가 맡겠사옵니다!","숨을 골라라! 겨누어라!","쏘아라! 한 발에 하나다!","한 발로 끝났사옵니다.","한 발이 모자랐사옵니다. 다시 쏘겠사옵니다."],art:["snipe","숨을 멈춰라! 한 발이면 된다!"],recorded:!0},"mujin-2":{voice:"Rina",style:"스물둘의 신명 많은 젊은 무당. 열정적이고 흥이 넘치며, 세고 맑게 노래하듯 신 내린 기운으로 말한다.",tap:["둥둥, 북이 울렸사옵니다.","굿판에서 왔사옵니다.","방울이 부르옵니다."],obey:["신명 나게 받들겠사옵니다.","굿 한 판으로 열겠사옵니다.","북 따라 다녀오겠사옵니다."],auto:["둥둥, 이 싸움은 굿판이옵니다!","북을 울려라! 신명 나게 밀어라!","방울을 흔들어라! 하늘이 내린다!","신령께서 기뻐하시옵니다.","굿이 덜 끝났사옵니다. 다시 올리겠사옵니다."],art:["rite","북을 울려라! 신령이여, 우리 군사에게 내리소서!"],recorded:!0},"hwanna-ruler":{voice:"Sulafat",style:"서른둘의 요염하고 여유로운 여인. 실리에 밝고 느긋하며, 눈을 가늘게 뜨고 요염하게 웃으며 거래하듯 말한다.",tap:["<laugh> 거래이옵니까?","무엇을 주시겠사옵니까?","셈하던 참이옵니다."],obey:["조건이 맞으니 하겠사옵니다.","곳간을 불려 드리겠사옵니다.","주고받는 대로 하겠사옵니다."],auto:["이 싸움, 값을 셈해 두었사옵니다!","물러나라! 쫓아오면 그때 받는다!","서두르지 마라! 거래는 끝까지다!","<laugh> 좋은 거래였사옵니다.","손해 본 거래이옵니다. 곱절로 받겠사옵니다."],art:["feint","여우처럼 물러나라! 쫓아오면 감싸 쳐라!"],recorded:!0},"goguryeo-2":{voice:"Laomedeia",style:"스물여섯의 또렷한 미인. 자신만만하고 호승심이 강하며 조금 도도하게, 맑고 힘 있는 목소리로 자신 있게 미소 지으며 말한다.",tap:["<laugh> 부르셨사옵니까.","이름값을 할 때이옵니까?","겨눌 곳을 이르시옵소서."],obey:["이름을 걸고 하겠사옵니다.","부끄럽지 않게 쏘겠사옵니다.","제게 맡기시옵소서."],auto:["혜미의 이름을 걸고 쏘겠사옵니다!","시위를 당겨라! 한 발도 지지 마라!","쏘아라! 고구려 활맛을 보여라!","<laugh> 이름값은 했사옵니다.","부끄럽사옵니다. 다시 이름을 걸겠사옵니다."],art:["snipe","이름을 걸고 쏜다! 적장의 투구를 꿰뚫어라!"],recorded:!0},"yeonna-1":{voice:"Lumi",style:"스물일곱의 단정하고 침착한 미인. 노련하고 고요하며, 잔잔하고 고른 맑은 목소리로 입가에 엷은 미소를 머금고 말한다.",tap:["안개 속에서 왔사옵니다.","길은 살펴 두었사옵니다.","<laugh> 부르셨사옵니까."],obey:["군사는 제가 이끌겠사옵니다.","안개 속도 훤하옵니다.","차분히 다녀오겠사옵니다."],auto:["산안개 속 길은 제가 아옵니다!","안개 속에 숨어라! 기다려라!","지금이다! 안개를 타고 쳐라!","길을 잃은 자는 없사옵니다.","안개가 짙었사옵니다. 다시 살피겠사옵니다."],art:["ambush","산안개를 타고 돌아라! 적의 등을 쳐라!"],recorded:!0},"yangmaek-1":{voice:"Nyla",style:"스물둘의 새침한 산골 아가씨. 퉁명스럽고 무뚝뚝하지만 속정이 깊으며, 맑고 곧은 목소리로 짧게 툭 말한다.",tap:["왜 부르셨사옵니까.","예. 왔사옵니다.","물고기 굽던 참이옵니다."],obey:["하라시면 하겠사옵니다.","알아서 해 두겠사옵니다.","물길로 다녀오겠사옵니다."],auto:["물길은 제가 맡겠사옵니다!","골짜기 물길로 돌아라! 조용히!","알아챌 땐 늦었다! 덮쳐라!","이겼사옵니다. 별것 아니었사옵니다.","분하옵니다. 다음엔 안 지겠사옵니다."],art:["ambush","골짜기 물길로 숨어들어라! 알아챌 땐 늦었다!"],recorded:!0},"wander-05":{voice:"Zuri",style:"스물의 수줍고 맑은 시골 아가씨. 꼼꼼하고 알뜰하며 조심스럽게, 수줍게 살포시 웃으며 조용히 말한다.",tap:["<laugh> 부르셨사옵니까.","낟알 세던 참이옵니다.","곳간은 잠가 두었사옵니다."],obey:["한 톨도 새지 않게 하겠사옵니다.","꼼꼼히 해 두겠사옵니다.","때 맞춰 거두겠사옵니다."],auto:["소녀가 한 톨도 안 빼앗기겠사옵니다!","곳간을 지켜라! 물러서지 마라!","모두 힘을 모아라! 소리를 높여라!","<laugh> 한 톨도 안 잃었사옵니다.","송구하옵니다. 낟알을 흘렸사옵니다."],art:["shout","곳간이 뒤에 있다! 모두 힘껏 소리쳐라!"],recorded:!0},"wander-07":{voice:"Tari",style:"스물셋의 신비롭고 귀한 아가씨. 고요하고 아득하며 하늘하늘 기품 있게, 입가에 엷은 미소를 머금고 꿈결처럼 말한다.",tap:["신령께서 이르시기를.","눈이 그쳤사옵니다.","하문하시옵소서."],obey:["신령의 뜻대로 하겠사옵니다.","눈길을 밟고 오겠사옵니다.","그리하라 하셨사옵니다."],auto:["신령께서 이 싸움을 맡기셨사옵니다!","눈보라를 타고 나아가라!","두려워 마라! 신령이 지켜 준다!","<laugh> 신령께서 웃으셨사옵니다.","눈이 다시 내리옵니다. 기다리겠사옵니다."],art:["rite","신령이시여, 눈보라 속 우리 군사를 지키소서!"],recorded:!0},"wander-08":{voice:"Tova",style:"서른의 사납고 자존심 높은 여전사. 과묵하고 날 서 있으며, 맑고 힘 있는 여기사 목소리로 짧게 말한다.",tap:["범 굴에서 왔사옵니다.","말씀하시옵소서.","창끝은 서 있사옵니다."],obey:["넷째 범으로 삼겠사옵니다.","물러서지 않사옵니다.","잡아 오겠사옵니다."],auto:["범 잡던 창이 맡겠사옵니다!","물가에 엎드려라! 숨죽여라!","덮쳐라! 목을 노려라!","넷째 범을 잡았사옵니다.","놓쳤사옵니다. 다시 쫓겠사옵니다."],art:["ambush","물가 갈대에서 일어나라! 범 잡듯 덮쳐라!"],recorded:!0},"wander-10":{voice:"Erinome",style:"열여덟의 상냥하고 발랄한 아가씨. 눈치 빠르고 애교 있으며, 생글생글 활짝 웃으며 통통 튀게 말한다.",tap:["<laugh> 부르셨사옵니까!","좋은 물건 있사옵니다!","값은 잘 쳐 주시옵니까?"],obey:["값진 것을 가져오겠사옵니다!","소녀가 먼저 다녀오겠사옵니다.","웃으며 흥정하고 오겠사옵니다."],auto:["소녀가 웃으며 이겨 보이겠사옵니다!","목청껏 외쳐라! 기운을 내라!","다 함께 밀어라! 흥을 올려라!","<laugh> 값진 승리이옵니다!","밑졌사옵니다. 다음엔 값을 올리겠사옵니다."],art:["shout","힘을 내라! 이기면 값진 것을 나눠 주마!"],recorded:!0},"wander-21":{voice:"Despina",style:"스물셋의 요염하고 도발적인 미인. 변덕스럽고 자신만만하며 슬쩍 떠보듯, 고개를 기울여 눈웃음치며 장난스럽게 말한다.",tap:["<laugh> 심심하던 참이옵니다.","쌍칼은 갈아 두었사옵니다.","재미있는 일이옵니까?"],obey:["재미있겠사옵니다. 가겠사옵니다.","어느 칼부터 쓰시겠사옵니까?","<laugh> 놀아 주고 오겠사옵니다."],auto:["이 싸움은 재미있겠사옵니다!","흔들어라! 마음부터 베어라!","웃으며 꾀어라! 넘어오게 하라!","재미있었사옵니다. 또 하시겠사옵니까?","재미가 없었사옵니다. 다음엔 이기겠사옵니다."],art:["sway","칼을 버려라! 재미있는 쪽으로 넘어오너라!"],recorded:!0},"wander-22":{voice:"Lora",style:"스물둘의 담담하고 당찬 아가씨. 말을 아끼고 곧으며, 맑고 시원한 여인의 목소리로 차분하게 말한다.",tap:["물에서 막 나왔사옵니다.","소문을 들었사옵니다.","말씀하시옵소서."],obey:["숨을 아끼고 다녀오겠사옵니다.","소문은 망태에 담아 오겠사옵니다.","받들겠사옵니다."],auto:["물속 길은 제가 맡겠사옵니다!","물밑에 숨어라! 숨을 아껴라!","지금 올라라! 뱃전을 잡아라!","물결 너머까지 소문나겠사옵니다.","숨이 짧았사옵니다. 다시 들어가겠사옵니다."],art:["ambush","물밑에서 솟구쳐라! 갈고리로 끌어내려라!"],recorded:!0},"jm-jumong":{voice:"Iapetus",style:"스무 살의 당당한 젊은 명궁이자 영웅. 맑고 힘 있는 청년 장수의 목소리로, 자신감 있되 예를 갖추어 또렷하게 말한다.",tap:["부르셨사옵니까.","활은 늘 당겨 두었사옵니다.","하늘이 보고 계시옵니다. 말씀하소서."],obey:["명대로 하겠사옵니다.","한 살로 꿰어 보이겠사옵니다.","맡겨 주소서. 빗나가지 않사옵니다."],auto:["이 싸움은 제 활에 맡기소서!","하늘이 우리 편이다! 앞으로!","겨누어라! 한 살도 헛되이 쏘지 마라!","하늘이 도우셨사옵니다.","활시위를 다시 매겠사옵니다."],art:["snipe","저 깃발 아래 장수를 꿰겠다! 숨을 멈춰라!"],recorded:!0,male:!0},"mh-onjo":{voice:"Orus",style:"스물둘의 의젓한 젊은 왕재. 단정하고 진지한 청년의 목소리로, 말을 곧고 짧게 끊어 침착하게 말한다.",tap:["예.","부르셨사옵니까.","말씀하소서. 듣겠사옵니다."],obey:["그리하겠사옵니다.","뜻대로 하겠사옵니다.","반드시 해내겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","물러서지 마라! 새 나라가 여기서 선다!","함께 간다! 앞으로!","이겼사옵니다. 백성부터 살피겠사옵니다.","송구하옵니다. 다시 세우겠사옵니다."],art:["sway","칼을 거두어라! 우리와 함께 새 나라를 세우자!"],recorded:!0,male:!0},"sr-hyeokgeose":{voice:"Koda",style:"열여덟의 맑고 고운 소년 왕. 티 없이 맑고 부드러운 소년의 목소리로, 너그럽고 따뜻하게 말한다.",tap:["부르셨사옵니까.","예, 여기 있사옵니다.","무슨 일이옵니까."],obey:["마음을 다하겠사옵니다.","그리하겠사옵니다.","백성을 위한 일이라면 기꺼이 하겠사옵니다."],auto:["다치는 이 없이 끝내겠사옵니다!","두려워 마라! 하늘이 굽어보신다!","함께 나아가자! 이 땅을 지킨다!","모두 무사하니 다행이옵니다.","제 탓이옵니다. 다시 품어 보겠사옵니다."],art:["sway","싸움을 멈추어라! 그대들도 이 땅의 사람이다!"],recorded:!0,male:!0},"tut-biryu":{voice:"Schedar",style:"스물일곱의 패기 넘치는 사내. 힘차고 시원한 젊은 장수의 목소리로, 자신만만하고 고집 있게 말한다.",tap:["왔사옵니다.","무슨 일이옵니까.","망치는 늘 손에 있사옵니다."],obey:["제 방식대로 해내겠사옵니다.","두고 보소서.","맡기셨으니 끝을 보겠사옵니다."],auto:["이 싸움은 제가 끝내겠사옵니다!","내 뒤를 따르라! 바다까지 간다!","줄을 맞춰라! 흩어지지 마라!","보셨사옵니까. 제 말이 옳았사옵니다.","이번만이옵니다. 다음엔 지지 않사옵니다."],art:["order","줄을 세워라! 방패를 붙여라! 내 북에 맞춰 나아간다!"],recorded:!0,male:!0},"jm-daeso":{voice:"Varo",style:"스물넷의 오만한 왕자. 곱상하지만 거들먹거리는 젊은 사내의 목소리로, 마지못해 하는 듯 비웃으며 말한다.",tap:["흥, 또 무엇이옵니까.","술잔을 두고 왔사옵니다.","말씀해 보시지요."],obey:["흥, 하라시면 하지요.","부여의 맏이가 몸소 하겠사옵니다.","이 정도쯤이야."],auto:["흥, 이런 싸움쯤은 제게 맡기시지요!","쓸어버려라! 부여의 칼맛을 보여라!","머뭇거리지 마라! 내가 앞이다!","흥, 당연한 일이옵니다.","흥, 오늘은 운이 없었을 뿐이옵니다."],art:["vanguard","비켜라! 부여의 맏이가 친히 나선다!"],recorded:!0,male:!0},"jm-oi":{voice:"Bodi",style:"서른넷의 굳은 무장. 단단하고 묵직한 사내의 목소리로, 짧고 힘 있게 끊어 말한다.",tap:["예.","부르셨사옵니까.","제가 앞서겠사옵니다."],obey:["명 받들겠사옵니다.","길은 제가 열겠사옵니다.","산길이라면 맡겨 주소서."],auto:["제가 앞서겠사옵니다! 따라오라!","창을 세워라! 물러서지 않는다!","밀어붙여라! 지금이다!","이겼사옵니다. 다친 이 없사옵니다.","면목 없사옵니다. 다시 앞서겠사옵니다."],art:["ambush","산등성이를 넘어라! 저들 뒤를 친다!"],recorded:!0,male:!0},"jm-mari":{voice:"Algenib",style:"서른여섯의 건장하고 과묵한 사내. 낮고 굵은 목소리로, 투박하게 짧게 끊어 말한다. 껄껄대지 않는다.",tap:["예.","왔사옵니다.","시키실 일이 있사옵니까."],obey:["하겠사옵니다. 그뿐이옵니다.","건널 길은 내겠사옵니다.","맡겨 주소서."],auto:["물길은 제가 아옵니다! 따라오라!","밧줄을 당겨라! 건너간다!","버텨라! 한 걸음도 밀리지 마라!","이겼사옵니다. 그뿐이옵니다.","졌사옵니다. 다시 하겠사옵니다."],art:["ambush","여울 아래로 숨어라! 물을 건너 뒤를 쳐라!"],recorded:!0,male:!0},"jm-hyeopbo":{voice:"Alnilam",style:"서른여덟의 침착한 책사. 고르고 차분한 중년 사내의 목소리로, 서두르지 않고 또박또박 말한다.",tap:["부르셨사옵니까.","판은 늘 펼쳐 두었사옵니다.","한 수만 더 보시지요."],obey:["서두르지 않되 지지 않겠사옵니다.","헤아려 두겠사옵니다.","그 수, 받겠사옵니다."],auto:["이 판은 제게 맡기소서!","서두르지 마라! 저들이 먼저 무너진다!","물러나는 척하라! 그리고 돌아서라!","수를 읽은 대로였사옵니다.","한 수가 모자랐사옵니다. 다시 두겠사옵니다."],art:["feint","물러나라! 저들이 쫓아오면 그때 돌아서 친다!"],recorded:!0,male:!0},"mh-ogan":{voice:"Brio",style:"마흔둘의 노련한 궁장. 단단하고 낮은 중년 사내의 목소리로, 흔들림 없이 차분하고 단정하게 말한다.",tap:["예.","부르셨사옵니까.","화살은 채워 두었사옵니다."],obey:["받들겠사옵니다.","밤이라도 과녁은 보이옵니다.","하나씩 꿰겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","숨을 고르고 겨누어라!","쏘아라! 한 줄로 쏟아부어라!","모두 맞혔사옵니다.","빗나갔사옵니다. 다시 겨누겠사옵니다."],art:["snipe","저 장수다! 숨을 멈추고 한 살로 꿰라!"],recorded:!0,male:!0},"tut-maryeo":{voice:"Rami",style:"마흔둘의 순박한 농사꾼. 따뜻하고 푸근한 중년 사내의 목소리로, 소박하게 웃으며 말한다.",tap:["예, 논에서 왔사옵니다.","부르셨사옵니까.","무엇을 하오리까."],obey:["부지런히 하겠사옵니다.","논물 대듯 차근차근 하겠사옵니다.","예, 맡겨 주시옵소서."],auto:["배불리 먹었으니 힘껏 싸우자!","곳간을 지켜라! 우리 논이다!","괭이 쥐던 손으로 칼을 쥔다! 나아가라!","이겼사옵니다. 가을이 기다리옵니다.","송구하옵니다. 내년에 다시 거두겠사옵니다."],art:["shout","우리 논을 지킨다! 함성을 올려라!"],recorded:!0,male:!0},"mh-eureum":{voice:"Umbriel",style:"마흔여섯의 여유 있는 책사. 느긋하고 부드러운 중년 사내의 목소리로, 속을 다 아는 듯 엷게 웃으며 차분히 말한다.",tap:["흠, 부르셨사옵니까.","말씀하소서.","흠, 무엇을 헤아리오리까."],obey:["흠, 그리하겠사옵니다.","꾀는 쓸 자리가 있사옵니다. 맡겨 주소서.","조용히 해 두겠사옵니다."],auto:["흠, 이 싸움은 제가 풀겠사옵니다!","서두르지 마라! 저들이 먼저 지친다!","거짓으로 물러나라! 그리고 덮쳐라!","흠, 헤아린 대로이옵니다.","흠, 제가 잘못 읽었사옵니다."],art:["feint","흩어져 달아나라! 쫓아오면 그때 돌아선다!"],recorded:!0,male:!0},"sr-alpyeong":{voice:"Cruz",style:"쉰의 신중한 촌장. 차분하고 낮은 중년 사내의 목소리로, 말을 아끼며 조심스럽게 말한다.",tap:["예.","부르셨사옵니까.","살펴보겠사옵니다."],obey:["셈해 보고 하겠사옵니다.","틀림없이 하겠사옵니다.","받들겠사옵니다."],auto:["이 싸움은 제가 살피겠사옵니다!","함부로 나서지 마라! 자리를 지켜라!","지금이다! 밀어라!","셈한 대로이옵니다.","셈이 틀렸사옵니다. 다시 하겠사옵니다."],art:["shout","마을을 지킨다! 함성을 올려라!"],recorded:!0,male:!0},"jm-songyang":{voice:"Charon",style:"쉰둘의 노련한 왕. 품위 있고 무게 있는 장년 사내의 목소리로, 체면을 세워 점잖게 말한다.",tap:["부르셨사옵니까.","말씀하시지요.","늙은이가 여기 있사옵니다."],obey:["체면을 걸고 해내겠사옵니다.","그리하겠사옵니다.","오랜 경험으로 받들겠사옵니다."],auto:["이 싸움은 이 늙은이가 맡겠사옵니다!","비류국의 이름을 걸어라! 물러서지 마라!","북을 울려라! 앞으로!","체면은 지켰사옵니다.","부끄럽사옵니다. 다시 일어서겠사옵니다."],art:["shout","북을 울려라! 우리 이름을 하늘에 외쳐라!"],recorded:!0,male:!0},"sr-hogong":{voice:"Knox",style:"쉰여섯의 넉살 좋은 늙은 장사꾼. 따뜻하고 구수한 장년 사내의 목소리로, 허허 웃으며 능청스럽게 말한다.",tap:["<laugh> 허허, 부르셨사옵니까.","예, 박 차고 왔사옵니다.","허허, 무슨 셈이옵니까."],obey:["허허, 손해 볼 일은 없사옵니다.","말로 풀 일이면 맡겨 주소서.","셈은 맞춰 두겠사옵니다."],auto:["허허, 이 싸움은 제가 맡지요!","겁먹지 마라! 셈은 우리가 남는다!","힘내라! 이기면 넉넉히 나눈다!","<laugh> 허허, 남는 장사였사옵니다.","허허, 이번엔 밑졌사옵니다."],art:["shout","허허, 기운들 내라! 이기면 한 상 크게 차린다!"],recorded:!0,male:!0},"saro-1":{voice:"Achird",style:"서른여덟의 우직한 수비 장수. 무난하고 단단한 사내의 목소리로, 서두르지 않고 짧고 묵직하게 말한다.",tap:["성문을 보고 왔사옵니다.","창은 세워 두었사옵니다.","무엇을 지키오리까."],obey:["버티라 하시면 버티겠사옵니다.","뿌리내리듯 지키겠사옵니다.","받들어 행하겠사옵니다."],auto:["이 싸움은 제가 버티겠사옵니다!","방패를 붙여라! 한 발도 내주지 마라!","버텼으면 이제 밀어라!","성문은 그대로이옵니다.","밀렸사옵니다. 다시 뿌리내리겠사옵니다."],art:["vanguard","방패를 앞세워라! 내가 먼저 밀고 들어간다!"],recorded:!0,male:!0},"wander-26":{voice:"Algieba",style:"서른의 호방한 미남 무장. 시원하고 우렁찬 사내의 목소리로, 껄껄 웃으며 자신만만하게 말한다.",tap:["<laugh> 하하, 왔사옵니다!","술 박은 비워 두었사옵니다.","언월도가 근질거리옵니다."],obey:["하하, 시원하게 해치우겠사옵니다.","한번 모셨으니 끝까지 가옵니다.","천둥처럼 다녀오겠사옵니다."],auto:["이런 판이 제일 신나옵니다!","언월도를 따르라! 크게 휘두른다!","기죽지 마라! 끝까지 간다!","하하, 이긴 술은 달겠사옵니다.","오늘은 쓴 술이옵니다. 다음엔 이기겠사옵니다."],art:["sway","칼을 내려라! 이리 와서 술 한 박 나누자!"],recorded:!0,male:!0},"maek-ruler":{voice:"Arlo",style:"서른의 집요한 밤 사냥꾼. 낮게 깔린 차분하고 서늘한 사내의 목소리로, 감정을 누르고 짧게 말한다.",tap:["어둠 속에 있었사옵니다.","밤이 오길 기다렸사옵니다.","노릴 것을 일러 주소서."],obey:["놓치지 않겠사옵니다.","어둠을 타고 가겠사옵니다.","한번 노리면 끝까지이옵니다."],auto:["이 밤은 제 사냥터이옵니다!","불을 꺼라! 숨소리도 죽여라!","쫓아라! 끝까지 물고 늘어져라!","사냥은 끝났사옵니다.","놓쳤사옵니다. 다음 밤엔 놓치지 않사옵니다."],art:["ambush","어둠 속에서 시위를 당겨라! 지금 덮쳐라!"],recorded:!0,male:!0},"guya-1":{voice:"Charon",style:"서른여덟의 위엄 있는 가야 쇠 무장. 무겁고 웅장한 영웅의 목소리로, 웃지 않고 군령처럼 힘 있게 끊어 말한다.",tap:["명만 내리시옵소서.","군사는 세워 두었사옵니다.","쇠칼은 날이 서 있사옵니다."],obey:["군령대로 하겠사옵니다.","천 군사로 해내겠사옵니다.","어김없이 받들겠사옵니다."],auto:["쇠칼 든 군사는 제가 이끌겠사옵니다!","줄을 맞춰라! 쇠 갑옷은 뚫리지 않는다!","베어라! 한 치도 물러서지 마라!","군령대로 끝났사옵니다.","군을 다시 세우겠사옵니다."],art:["vanguard","고리칼을 뽑아라! 내가 앞장서 길을 연다!"],recorded:!0,male:!0},"guga-1":{voice:"Daro",style:"스물셋의 날렵한 젊은 사냥꾼. 젊지만 낮게 가라앉은 사내의 목소리로, 날 서게 짧게 말한다.",tap:["냄새를 맡고 왔사옵니다.","이리 떼는 깨어 있사옵니다.","쫓을 것이 있사옵니까."],obey:["물면 놓지 않사옵니다.","냄새를 따라가겠사옵니다.","곧 찾아내겠사옵니다."],auto:["쫓는 일은 제게 맡기소서!","흩어져 에워싸라! 숨통을 조여라!","놓치지 마라! 냄새가 짙다!","다 찾아냈사옵니다.","냄새를 놓쳤사옵니다. 다시 쫓겠사옵니다."],art:["ambush","이리 떼처럼 숨었다가 한꺼번에 물어라!"],recorded:!0,male:!0},"wander-25":{voice:"Elio",style:"스물셋의 차갑고 오만한 칼잡이. 낮고 서늘한 젊은 사내의 목소리로, 말을 아끼며 끝을 짧게 끊는다.",tap:["이름만 일러 주소서.","칼은 쉬고 있사옵니다.","또 무슨 일이옵니까."],obey:["말은 필요 없사옵니다.","끝내고 오겠사옵니다.","밤에 가겠사옵니다."],auto:["이 칼로 충분하옵니다!","소리 내지 마라. 베어라!","하나도 남기지 마라!","싱겁게 끝났사옵니다.","다음엔 이리 안 되옵니다."],art:["sway","칼을 버려라. 살고 싶은 자만 건너오라!"],recorded:!0,male:!0},"sr-sobeol":{voice:"Enzo",style:"일흔둘의 인자한 마을 큰어른. 느릿하고 따뜻한 노인의 목소리로, 허허 웃으며 너그럽게 말한다.",tap:["<laugh> 허허, 늙은이 왔사옵니다.","조 이삭이 잘 여물었사옵니다.","천천히 말씀하소서."],obey:["허허, 서두르지 않고 하겠사옵니다.","여섯 마을이 힘을 보태겠사옵니다.","익을 때를 기다려 거두겠사옵니다."],auto:["늙었어도 마을은 제가 지키겠사옵니다!","여섯 마을이 함께다! 물러서지 마라!","젊은이들아, 힘을 내라! 앞으로!","허허, 잘 여물었사옵니다.","서리를 맞았사옵니다. 내년을 보겠사옵니다."],art:["shout","여섯 마을이여, 일어나라! 함성을 올려라!"],recorded:!0,male:!0},"yeonna-ruler":{voice:"Gero",style:"쉰여섯의 의심 많은 늙은 귀족. 느리고 낮은 장년 사내의 목소리로, 수염을 쓸며 따지듯 신중하게 말한다.",tap:["흠, 무슨 일이옵니까.","지켜보고 있었사옵니다.","백성은 배부르옵니까."],obey:["흠, 따져 보고 하겠사옵니다.","백성이 굶지 않는 길로 하겠사옵니다.","서두르지 않겠사옵니다."],auto:["이 싸움은 제가 따져 보겠사옵니다!","덥석 물지 마라! 저들 속을 보아라!","물러나는 척하라! 쫓아오면 감싸라!","지켜본 보람이 있사옵니다.","때를 놓쳤사옵니다. 다시 살피겠사옵니다."],art:["feint","등을 보여라! 저들이 쫓아오면 그때 돌아선다!"],recorded:!0,male:!0},"anya-ruler":{voice:"Knox",style:"스물아홉의 영리한 미남 책사. 부드럽고 여유 있는 젊은 사내의 목소리로, 엷게 웃으며 느긋하게 말한다.",tap:["잔을 내려놓고 왔사옵니다.","헤아려 보았사옵니다.","몇 수 앞을 보고 있었사옵니다."],obey:["이미 헤아려 두었사옵니다.","웃으며 끝내 오겠사옵니다.","그 수라면 좋사옵니다."],auto:["세 수 앞은 이미 보았사옵니다!","서두르지 마라! 저들이 먼저 걸린다!","빈 곳을 내주어라! 들어오면 닫아라!","잔을 들어도 되겠사옵니다.","제 셈이 얕았사옵니다. 다시 짜겠사옵니다."],art:["feint","물러나 길을 열어라! 들어오면 문을 닫는다!"],recorded:!0,male:!0},"wander-14":{voice:"Mako",style:"마흔의 듬직한 기수. 낮고 굵은 중년 사내의 목소리로, 정중하고 굳게 말한다.",tap:["깃발 들고 왔사옵니다.","장정들은 모여 있사옵니다.","분부를 기다리옵니다."],obey:["깃발을 앞세우겠사옵니다.","변함없이 받들겠사옵니다.","마을 장정과 함께 가겠사옵니다."],auto:["깃발은 제가 들겠사옵니다! 따르라!","깃발을 보아라! 쓰러지지 않는다!","서로의 이름을 불러라! 버텨라!","깃발은 아직 서 있사옵니다.","깃발이 꺾였사옵니다. 다시 세우겠사옵니다."],art:["stand","하나씩 이름을 부른다! 대답하라, 그리고 버텨라!"],recorded:!0,male:!0},"dokro-2":{voice:"Milo",style:"마흔여덟의 무뚝뚝한 노병. 거칠고 낮은 중년 사내의 목소리로, 경계하듯 짧고 무뚝뚝하게 말한다.",tap:["성벽을 돌고 왔사옵니다.","문 앞은 살펴 두었사옵니다.","수상한 자는 없사옵니다."],obey:["뒤는 제가 지키겠사옵니다.","돌 하나까지 살피겠사옵니다.","알겠사옵니다. 가옵니다."],auto:["문 앞은 제가 지키겠사옵니다!","두리번거리지 마라! 앞만 보라!","버텨라! 늙은 칼도 아직 벤다!","살펴 둔 대로이옵니다.","제 눈이 흐렸사옵니다. 다시 살피겠사옵니다."],art:["shout","칼을 들어라! 이 문은 아무도 못 넘는다!"],recorded:!0,male:!0},"goja-ruler":{voice:"Neno",style:"쉰둘의 능글맞은 흥정꾼. 수염 많은 중년 사내의 굵고 넉살 좋은 목소리로, 저울질하듯 느긋하게 웃으며 말한다.",tap:["소금 자루 두고 왔사옵니다.","무엇을 사고파오리까.","<laugh> 이문 남는 일이옵니까."],obey:["셈이 맞사옵니다. 하겠사옵니다.","배 띄우고 다녀오겠사옵니다.","덩이쇠 값은 받아 오겠사옵니다."],auto:["물길 싸움은 제게 맡기소서!","배를 숨겨라! 저들이 지나가게 두어라!","이문은 우리 것이다! 밀어붙여라!","셈이 딱 맞았사옵니다.","값을 잘못 매겼사옵니다. 다시 흥정하겠사옵니다."],art:["ambush","물굽이에 숨긴 배를 띄워라! 뒤를 들이쳐라!"],recorded:!0,male:!0},"biryuna-1":{voice:"Olin",style:"스물하나의 장난스러운 미소년 뱃사공. 맑고 가벼운 미성의 젊은 사내 목소리로, 웃으며 능청스럽게 말한다.",tap:["<laugh> 노 젓다 왔사옵니다.","물길이 부르옵니까.","뱃머리만 잡으소서."],obey:["길은 제가 내지요.","물살 타고 금방 다녀오겠사옵니다.","어려울 것 없사옵니다."],auto:["물길이라면 제 차지이옵니다!","노를 저어라! 물살을 타라!","웃으며 따라오라! 길은 열렸다!","물 흐르듯 이겼사옵니다.","물살이 거꾸로였사옵니다. 다시 타겠사옵니다."],art:["ambush","물안개 속에서 뱃머리를 돌려라! 들이받아라!"],recorded:!0,male:!0,shoutStyle:"스물하나의 젊은 뱃사공. 맑은 젊은 사내 목소리지만 싸움에서는 장난기 없이 힘차고 짧게 끊어 외친다. 말끝을 노래하듯 늘이지 않는다."},"jomun-1":{voice:"Puck",style:"서른아홉의 냉소적인 매눈 사냥꾼. 낮고 건조한 사내의 목소리로, 한쪽 입꼬리를 올린 듯 시큰둥하게 말한다.",tap:["다 보았사옵니다.","하늘에서 보듯 보고 있사옵니다.","무엇을 찾으시옵니까."],obey:["제 눈으로 보고 오겠사옵니다.","숨어도 소용없사옵니다.","내려다보고 오겠사옵니다."],auto:["어둠 속의 적은 제가 찾겠사옵니다!","눈을 떠라! 저 풀숲이다!","매처럼 내리꽂아라! 채어 올려라!","숨은 놈까지 다 보았사옵니다.","제 눈이 어두웠사옵니다."],art:["ambush","어둠에 엎드려라! 내 살이 날면 덮쳐라!"],recorded:!0,male:!0},"bukokjeo-ruler":{voice:"Rami",style:"마흔여섯의 담담한 북녘 사내. 낮고 고요한 중년 사내의 목소리로, 웃지 않고 묵묵하게 말한다.",tap:["눈을 털고 왔사옵니다.","추위는 견딜 만하옵니다.","말씀을 기다리옵니다."],obey:["묵묵히 해내겠사옵니다.","눈길이라도 가겠사옵니다.","오래 걸려도 끝을 보겠사옵니다."],auto:["견디는 싸움은 제게 맡기소서!","눈보라를 등에 져라! 버텨라!","산을 타고 내려가라! 조용히!","견딘 보람이 있사옵니다.","겨울이 길었사옵니다. 다시 견디겠사옵니다."],art:["ambush","눈 덮인 고개에 엎드려라! 지나가면 덮쳐라!"],recorded:!0,male:!0},"wander-23":{voice:"Rasalgethi",style:"스물둘의 능글맞은 꽃미남 궁수. 가볍고 매끄러운 젊은 사내의 목소리로, 한쪽 눈을 찡긋하듯 농을 섞어 말한다.",tap:["<laugh> 저를 찾으셨사옵니까?","활도 얼굴도 준비되었사옵니다.","오늘은 무엇을 맞히오리까."],obey:["한 발이면 되옵니다. 어떠하옵니까?","멋지게 다녀오겠사옵니다.","보는 눈이 많을수록 잘 쏘옵니다."],auto:["이 싸움, 제 활로 끝내면 어떠하옵니까!","한쪽 눈 감고 쏘아라! 그래도 맞는다!","쏘아라! 멋있게 쏘아라!","한 살도 안 빗나갔사옵니다.","바람이 시샘했사옵니다."],art:["snipe","눈 한쪽이면 충분하다! 적장 미간이다!"],recorded:!0,male:!0,shoutStyle:"스물둘의 젊은 궁수. 매끄러운 젊은 사내 목소리지만 싸움에서는 농 없이 날카롭고 짧게 끊어 외친다. 말끝을 늘이지 않는다."},"gammun-ruler":{voice:"Riko",style:"서른셋의 고요한 남자 무당. 나직하고 신비로운 사내의 목소리로, 꿈결처럼 차분하게 말한다.",tap:["꿈에 뵈었사옵니다.","방울이 저 혼자 울었사옵니다.","조상님이 깨어 계시옵니다."],obey:["조상님 뜻대로 하겠사옵니다.","꿈에 본 길로 가겠사옵니다.","거울에 비춰 보고 가겠사옵니다."],auto:["이 싸움은 꿈에 본 대로이옵니다!","두려워 마라! 조상이 지켜보신다!","연기를 따라 나아가라! 길이 열린다!","꿈이 맞았사옵니다.","꿈을 잘못 읽었사옵니다. 다시 여쭙겠사옵니다."],art:["rite","향을 피워라! 조상의 넋이여, 꿈에서 깨어나소서!"],recorded:!0,male:!0},"wander-17":{voice:"Sadachbia",style:"스물의 건방진 미소년 떠돌이. 가볍고 날렵한 젊은 사내의 목소리로, 반쯤 웃으며 능청스럽게 말한다.",tap:["<laugh> 품삯 주실 일이옵니까?","바람처럼 왔사옵니다.","값만 맞으면 듣겠사옵니다."],obey:["품삯만큼 하겠사옵니다.","산길 하나, 품삯 하나이옵니다.","값은 나중에 셈하시지요."],auto:["이 싸움은 값을 두 배로 받겠사옵니다!","바람처럼 돌아라! 옆을 쳐라!","산길로 빠져라! 따라오지 못한다!","품삯 값은 했사옵니다.","오늘 품삯은 안 받겠사옵니다."],art:["ambush","산바람 타고 돌아들어라! 등 뒤를 쳐라!"],recorded:!0,male:!0,shoutStyle:"스물의 날렵한 떠돌이. 가벼운 젊은 사내 목소리지만 싸움에서는 웃음기 없이 빠르고 짧게 끊어 외친다. 말끝을 늘이지 않는다."},"baekje-ruler":{voice:"Sadaltager",style:"마흔넷의 품위 있는 문무 겸한 신지. 단정하고 차분한 중년 사내의 목소리로, 정중하고 꼼꼼하게 말한다.",tap:["말씀을 받잡겠사옵니다.","두루마리는 펼쳐 두었사옵니다.","성은 빈틈없사옵니다."],obey:["꼼꼼히 살펴 행하겠사옵니다.","빈틈없이 하겠사옵니다.","예를 다해 받들겠사옵니다."],auto:["이 싸움은 제가 차근차근 풀겠사옵니다!","줄을 흩지 마라! 천천히 물러나라!","지금 돌아서라! 저들 옆을 쳐라!","빈틈없이 끝났사옵니다.","빈틈을 보였사옵니다. 다시 메우겠사옵니다."],art:["feint","천천히 물러나라! 깊이 들어오면 그때 돌아서라!"],recorded:!0,male:!0},"tamna-1":{voice:"Umbriel",style:"서른여덟의 소탈한 섬 사내. 후덕하고 넉넉한 사내의 목소리로, 햇볕처럼 웃으며 구수하게 말한다.",tap:["<laugh> 오름 하나 넘어왔사옵니다.","다리는 아직 튼튼하옵니다.","무엇이든 시키소서."],obey:["섬에서는 이쯤은 일도 아니옵니다.","부지런히 다녀오겠사옵니다.","몽둥이 메고 가겠사옵니다."],auto:["오르막 싸움은 제게 맡기소서!","언덕을 차지하라! 위에서 내리친다!","튼튼한 다리로 버텨라! 밀어라!","섬에서는 이런 걸 잔치라 하옵니다.","바람이 셌사옵니다. 다시 오르겠사옵니다."],art:["ambush","돌담 뒤에 엎드려라! 지나가면 몽둥이로 쳐라!"],recorded:!0,male:!0,shoutStyle:"서른여덟의 섬 사내. 후덕하고 넉넉한 사내 목소리로, 싸움에서는 우렁차고 짧게 끊어 외친다. 말끝을 늘이지 않는다."},"sr-hojin":{voice:"Zeno",style:"마흔여섯의 거친 산 사냥꾼. 투박하고 굵은 중년 사내의 목소리로, 묵묵하게 짧게 끊어 말한다.",tap:["도끼 들고 왔사옵니다.","산에서 내려왔사옵니다.","곰 발자국을 보고 왔사옵니다."],obey:["길은 도끼로 내겠사옵니다.","산이라면 제 집이옵니다.","말없이 해 오겠사옵니다."],auto:["산 싸움은 제가 맡겠사옵니다!","발을 박고 버텨라! 물러서지 마라!","도끼를 들어라! 찍어 넘겨라!","큰 짐승을 잡았사옵니다.","산이 노했사옵니다. 다시 오르겠사옵니다."],art:["ambush","바위 뒤에서 일어나라! 곰처럼 덮쳐라!"],recorded:!0,male:!0},"gj-dana":{voice:"Autonoe",style:"스물둘의 당당하고 고지식한 여기사. 명령에 곧게 따르며, 맑고 힘 있는 목소리로 단정하고 반듯하게 말한다. 군례를 갖춘 말투. 들뜨거나 발랄하지 않다.",tap:["예. 다나, 대령했사옵니다.","명을 내리시옵소서.","활도 칼도 갖추었사옵니다."],obey:["명을 받들겠사옵니다.","분부대로 어김없이 행하겠사옵니다.","지체 없이 다녀오겠사옵니다."],auto:["이 싸움, 명을 받들어 다나가 맡겠사옵니다!","대열을 지켜라! 명 없이 움직이지 마라!","가락의 군사다! 앞으로!","명하신 대로 이겼사옵니다.","면목 없사옵니다. 벌을 내리시옵소서."],art:["snipe","숨을 고르라. 이 한 발로 적장을 꿰뚫는다!"],recorded:!0},"gj-yucheongan":{voice:"Aoede",style:"서른다섯의 너그럽고 시원시원한 곳간지기, 마을의 큰언니. 밝고 따뜻한 30대 여인의 목소리로, 웃음기를 머금고 시원스럽게 말한다. 늙거나 쉰 목소리가 아니다.",tap:["곳간 열쇠 들고 왔사옵니다.","부르셨사옵니까? 무엇이든 말씀하시옵소서.","진지는 드셨사옵니까?"],obey:["걱정 마시옵소서. 제가 다 챙기겠사옵니다.","맡겨 두시옵소서. 넉넉히 해 두겠사옵니다.","금방 다녀오겠사옵니다."],auto:["이 싸움, 제가 맡겠사옵니다!","곳간을 지켜라! 한 톨도 내주지 마라!","뒤에 마을이 있다! 물러서지 마라!","이겼사옵니다! 오늘 밤은 다들 배불리 먹이겠사옵니다.","송구하옵니다. 다시 일으켜 세우겠사옵니다."],art:["feint","곳간이 비었다고 소문을 내라! 배고픈 적이 몰려들 때 친다!"],recorded:!0}},u={"tut-ogan":"mh-ogan","tut-malgalgi":"sabeol-1","jm-okjeo-ruler":"bukokjeo-ruler","tut-onjo":"mh-onjo"},l=e=>u[e]??e;function d(e){const a=l(e);return!0===y[a]?.recorded?`realm/voice/hero/${a}/`:null}const y={...t,"apdok-1":{voice:"Zeno",style:"쉰 살의 우직한 도끼잡이. 말수가 적고 투박하며 울림 있는 중년 사내의 목소리로, 한마디씩 무겁게 내려놓듯 말한다.",tap:["예.","도끼는 갈아 두었사옵니다.","여기 있사옵니다."],obey:["맡겨 주소서.","내리치면 끝이옵니다.","말보다 손이 먼저 나가옵니다."],auto:["도끼가 맡겠사옵니다!","앞을 막는 것은 쪼갠다! 나아가라!","물러서면 맞는다! 밀어붙여라!","끝났사옵니다. 도끼를 거두겠사옵니다.","무뎠사옵니다. 다시 갈겠사옵니다."],art:["vanguard","도끼가 먼저 간다! 내 등만 보고 따라와라!"],recorded:!0,male:!0},"baekje-1":{voice:"Puck",style:"마흔하나의 꼼꼼하고 능청스러운 장수. 차분한 중년 사내의 목소리로, 하나씩 짚어 가며 슬며시 웃음을 머금고 말한다.",tap:["예, 듣고 있사옵니다.","셈해 보고 오는 길이옵니다.","무슨 일이시옵니까."],obey:["셈해 보니 할 만하옵니다.","손해 볼 일은 아니옵니다. 맡겨 주소서.","차근차근 해 두겠사옵니다."],auto:["셈은 끝났사옵니다. 이 싸움은 제가 맡겠사옵니다!","앞이 얼마, 뒤가 얼마! 밀어붙여라!","셈한 대로 간다! 흔들리지 마라!","셈이 맞았사옵니다. 이겼사옵니다.","셈이 틀렸사옵니다. 다시 헤아리겠사옵니다."],art:["vanguard","셈은 끝났다! 내가 앞서니 한 걸음도 처지지 마라!"],recorded:!0,male:!0},"baekje-2":{voice:"Autonoe",style:"스물다섯의 도도하고 침착한 여궁수. 맑고 서늘한 목소리로 품위 있게, 높은 곳에서 내려다보듯 말한다.",tap:["말씀하시옵소서.","여기 있사옵니다.","매는 이미 날고 있사옵니다."],obey:["분부대로 하겠사옵니다.","한 번에 끝내 보이겠사옵니다.","맡겨 주시옵소서. 놓치지 않사옵니다."],auto:["이 싸움은 제 활이 맡겠사옵니다!","높이서 내려다보라! 흩어지는 쪽부터 쏜다!","숨을 고르라! 한꺼번에 내리꽂는다!","이겼사옵니다. 당연한 일이옵니다.","송구하옵니다. 다음엔 놓치지 않겠사옵니다."],art:["snipe","매가 내려앉는다! 적장의 목에 꽂아라!"],recorded:!0},"balla-ruler":{voice:"Schedar",style:"마흔다섯의 열정적인 제사장. 울림 있는 중년 사내의 목소리로, 신령께 고하듯 읊조리며 말한다.",tap:["신령께 고하고 왔사옵니다.","부르셨사옵니까.","말씀하소서. 하늘도 듣고 계시옵니다."],obey:["신령께 여쭙고 행하겠사옵니다.","제를 올려 길을 열겠사옵니다.","뜻을 받들겠사옵니다."],auto:["신령이 이 싸움을 맡으셨사옵니다!","두려워 마라! 신령이 우리 곁에 서셨다!","북을 울려라! 하늘이 듣는다!","신령께서 도우셨사옵니다.","제가 부족했사옵니다. 다시 제를 올리겠사옵니다."],art:["rite","신령이시여, 굽어보소서! 이 땅의 적을 물리쳐 주소서!"],recorded:!0,male:!0},"bihwa-1":{voice:"Daro",style:"마흔의 조용하고 괴짜 같은 늪 사냥꾼. 낮게 가라앉은 사내의 목소리로, 느릿느릿 말수 적게 말한다.",tap:["예.","늪에서 기다리고 있었사옵니다.","부르셨사옵니까."],obey:["기다리는 일이라면 맡겨 주소서.","숨죽이고 해내겠사옵니다.","때가 되면 움직이겠사옵니다."],auto:["늪이 삼키게 하겠사옵니다!","숨죽여라. 발이 빠지면 놓치지 마라!","끌어당겨라! 진흙 속으로!","기다린 보람이 있었사옵니다.","아직 때가 아니었사옵니다. 다시 기다리겠사옵니다."],art:["ambush","늪에서 일어나라! 발 묶인 놈들을 쳐라!"],recorded:!0,male:!0},"bihwa-ruler":{voice:"Tari",style:"스물넷의 신비롭고 우아한 제사장. 하늘하늘 고요한 목소리로, 마음을 어루만지듯 말한다.",tap:["부르셨사옵니까.","거울에 비치기를, 말씀하소서.","곁에 있사옵니다."],obey:["그리하겠사옵니다. 마음을 다하겠사옵니다.","거울에 비친 길을 따르겠사옵니다.","맡겨 주소서. 곱게 풀어 보이겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다. 지켜보소서!","거울을 들어라! 저들의 마음을 흔들어라!","칼을 내려라! 우리 곁으로 오너라!","고요히 끝났사옵니다.","마음이 닿지 못했사옵니다. 다시 닦겠사옵니다."],art:["sway","칼을 거두어라! 거울 속 그대들의 얼굴을 보라!"],recorded:!0},"biryuna-ruler":{voice:"Erinome",style:"스무 살의 다정하고 당당한 어린 패자. 맑고 또랑또랑한 목소리로, 격식을 갖추려 애쓰며 씩씩하게 말한다.",tap:["예, 여기 있사옵니다.","부르셨사옵니까.","말씀하소서. 듣겠사옵니다."],obey:["예를 다해 맡겠사옵니다.","부족하지만 힘껏 하겠사옵니다.","맡겨 주소서. 해내겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","물러서지 마라! 우리 부족의 이름을 걸었다!","함께 가자! 나를 믿어라!","모두의 덕이옵니다. 이겼사옵니다.","송구하옵니다. 더 배우고 오겠사옵니다."],art:["sway","창을 거두어라! 우리와 함께 가자!"],recorded:!0},"bullae-1":{voice:"Enzo",style:"예순여덟의 온화하고 노련한 마을 어른. 따뜻하고 느긋한 노인의 목소리로, 허허 웃으며 다정하게 말한다.",tap:["허허, 왔사옵니다.","무슨 일이시옵니까.","허허, 부르셨사옵니까."],obey:["허허, 맡겨 주소서.","천천히, 그러나 틀림없이 하겠사옵니다.","이 늙은 몸이 해 보겠사옵니다."],auto:["허허, 이 늙은이가 맡겠사옵니다!","서두르지 마라! 줄을 맞춰 나아가라!","발을 맞춰라! 흔들리지 마라!","허허, 이겼사옵니다. 다들 수고했소.","허허, 졌사옵니다. 그래도 사람은 남았사옵니다."],art:["order","줄을 맞춰라! 흔들리지 말고 한 걸음씩 나아가라!"],recorded:!0,male:!0},"buyeo-1":{voice:"Autonoe",style:"스물여덟의 냉정하고 기품 있는 부여 귀족 무장. 맑고 서늘한 목소리로, 절제하며 짧게 말한다.",tap:["예.","무슨 일이시옵니까.","듣고 있사옵니다."],obey:["받들겠사옵니다.","맡은 일은 어김없이 하겠사옵니다.","염려 마시옵소서."],auto:["이 싸움은 제가 맡겠사옵니다!","대열을 흩지 마라! 겨누어라!","한 발도 헛되이 쏘지 마라!","당연한 결과이옵니다.","송구하옵니다. 다시는 없을 일이옵니다."],art:["snipe","기품을 잃지 마라! 적장의 가슴을 꿰뚫는다!"],recorded:!0},"buyeo-ruler":{voice:"Puck",style:"쉰둘의 노회하고 품위 있는 옛 왕. 느리고 깊은 중년 사내의 목소리로, 상대의 그릇을 재며 낮게 웃듯 말한다.",tap:["부르셨사옵니까.","두고 보겠사옵니다.","말씀하소서."],obey:["두고 보되, 맡은 일은 하겠사옵니다.","그릇만큼 해 드리겠사옵니다.","그리하겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다. 두고 보소서!","대열을 갖춰라! 서두르는 쪽이 진다!","북소리에 맞춰라! 한 치도 흩어지지 마라!","저울이 기울었사옵니다. 이겼사옵니다.","한 수 졌사옵니다. 아직 판은 끝나지 않았사옵니다."],art:["order","대열을 갖춰라! 내 북소리에 맞춰 나아간다!"],recorded:!0,male:!0},"byeokjin-1":{voice:"Tari",style:"스물하나의 다정하고 꿈 많은 처녀. 맑고 고운 목소리로, 부드럽게 말한다.",tap:["부르셨사옵니까.","예, 여기 있사옵니다.","별이 곱사옵니다. 말씀하소서."],obey:["정성껏 하겠사옵니다.","밤새워서라도 해 두겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","별이 우리를 비춘다! 힘을 내라!","무서워 마라! 함께 나아가자!","이겼사옵니다. 모두 무사해서 다행이옵니다.","송구하옵니다. 다시 일어서겠사옵니다."],art:["shout","별이 우리를 비춘다! 힘을 내라, 함께 가자!"],recorded:!0},"byeokjin-ruler":{voice:"Nika",style:"스물셋의 씩씩하고 명랑한 대장장이 우두머리. 맑고 힘 있는 여기사 목소리로 시원스레 말한다.",tap:["풀무 앞에서 왔사옵니다.","부르셨사옵니까.","쇠는 달궈 두었사옵니다."],obey:["달굴 때 쳐야 하옵니다. 바로 하겠사옵니다.","단단히 벼려 놓겠사옵니다.","맡겨 주소서!"],auto:["쇠가 달았을 때 친다! 이 싸움은 제가 맡겠사옵니다!","풀무질하듯 몰아쳐라!","식기 전에 두들겨라!","잘 벼려졌사옵니다. 이겼사옵니다.","덜 달궜사옵니다. 다시 달구겠사옵니다."],art:["shout","불을 지펴라! 달았을 때 친다, 함성을 올려라!"],recorded:!0},chief:{voice:"Knox",style:"스물둘의 과묵하고 자부심 강한 젊은 궁수. 서늘하고 단정한 청년의 목소리로, 말수 적게 말한다.",tap:["예.","듣고 있사옵니다.","활은 준비되었사옵니다."],obey:["받들겠사옵니다.","놓치지 않겠사옵니다.","명대로 하겠사옵니다."],auto:["제 활에 맡기소서!","어둠이 와도 보인다! 겨누어라!","한 살도 헛되이 쏘지 마라!","끝났사옵니다.","물러서겠사옵니다. 다음엔 놓치지 않사옵니다."],art:["snipe","밤이 깊어도 보인다! 적장을 쏜다!"],recorded:!0,male:!0},"chopal-1":{voice:"Knox",style:"서른둘의 날카롭고 과묵한 척후. 서늘한 사내의 목소리로, 말을 아껴 짧게 말한다.",tap:["예.","물길은 읽어 두었사옵니다.","말씀하소서."],obey:["소리 없이 다녀오겠사옵니다.","건너가 보겠사옵니다.","받들겠사옵니다."],auto:["제가 앞서 건너겠사옵니다!","물소리에 숨어라! 소리 내지 마라!","여울을 건너 뒤를 쳐라!","돌아왔사옵니다. 이겼사옵니다.","물이 불었사옵니다. 다시 건너겠사옵니다."],art:["ambush","물소리에 숨어 건너라! 등 뒤에서 덮쳐라!"],recorded:!0,male:!0},"chopal-2":{voice:"Nika",style:"스물다섯의 사납고 우직한 창잡이. 맑고 힘 있는 여기사 목소리로, 투지를 담아 짧고 단단하게 말한다.",tap:["창은 들고 있사옵니다.","무슨 일이시옵니까.","싸울 곳이 있사옵니까."],obey:["창이 먼저 가겠사옵니다.","찔러서 길을 열겠사옵니다.","맡겨 주소서!"],auto:["창이 맡겠사옵니다!","앞을 찔러라! 멈추지 마라!","이름 대신 창으로 말해라!","이겼사옵니다. 창끝이 말했사옵니다.","창이 부러졌사옵니다. 다시 깎아 오겠사옵니다."],art:["ambush","풀숲에서 창을 세워라! 지나가는 자를 찔러라!"],recorded:!0},"chopal-ruler":{voice:"Arlo",style:"서른하나의 신중하고 냉정한 돌팔매꾼. 차분하고 건조한 사내의 목소리로, 한마디씩 짧게 말한다.",tap:["말씀하소서.","한 번이면 되옵니다.","듣고 있사옵니다."],obey:["한 번에 끝내겠사옵니다.","이길 판이면 하겠사옵니다.","맡겨 주소서."],auto:["한 번이면 되옵니다!","기다려라. 충분히 가까워질 때까지!","던져라! 한 번에 끝낸다!","한 번에 끝났사옵니다.","판을 잘못 골랐사옵니다. 물러나옵니다."],art:["ambush","돌을 쥐어라! 가까이 올 때까지 기다렸다 한꺼번에 던져라!"],recorded:!0,male:!0},"dabeol-1":{voice:"Mako",style:"서른일곱의 먹성 좋고 넉살 좋은 싸움꾼. 투박한 사내의 목소리로, 입에 뭘 문 듯 크게 웃으며 말한다.",shoutStyle:"서른일곱의 싸움꾼. 투박한 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["크하하! 왔사옵니다.","한 상 먹고 오겠사옵니다.","무슨 일이옵니까!"],obey:["한 상만 차려 주시면 하겠사옵니다!","먹고 나면 못 할 일이 없사옵니다.","크하하! 맡겨 주소서."],auto:["먹었으니 덤비겠사옵니다!","들개처럼 물어라! 놓지 마라!","뜯어라! 한 놈도 놓치지 마라!","크하하! 이겼으니 한 상 받겠사옵니다!","배가 고팠사옵니다. 먹고 다시 가겠사옵니다."],art:["vanguard","들개처럼 덤벼라! 내가 먼저 문다!"],recorded:!0,male:!0},"dabeol-2":{voice:"Zuri",style:"스물넷의 여유로운 여궁수. 맑고 고운 젊은 여인의 목소리로, 달밤에 살짝 웃듯 말한다.",tap:["달이 밝사옵니다.","부르셨사옵니까.","예, 듣고 있사옵니다."],obey:["달이 지기 전에 해 놓겠사옵니다.","웃으며 다녀오겠사옵니다.","맡겨 주소서."],auto:["달이 밝사옵니다. 제가 맡겠사옵니다!","숨어라! 달이 구름에 가릴 때 친다!","소리 없이 겨누어라!","달이 밝았사옵니다. 이겼사옵니다.","구름이 달을 가렸사옵니다. 물러나옵니다."],art:["ambush","달이 구름에 숨는다! 어둠 속에서 일어나 쏘아라!"],recorded:!0},"dabeol-ruler":{voice:"Neno",style:"쉰여섯의 호방하고 너그러운 산 주인. 수염 많은 어른의 넉넉한 목소리로, 허허 웃으며 말한다.",tap:["허허, 왔사옵니다.","산바람 쐬고 왔사옵니다.","부르셨사옵니까."],obey:["허허, 맡겨 주소서.","산길이라면 눈 감고도 가옵니다.","그리하겠사옵니다."],auto:["이 산 주인이 맡겠사옵니다!","산자락에 숨어라! 넘어오는 놈을 덮쳐라!","내 산에서 한 놈도 못 나간다!","허허, 이겼사옵니다. 술 한 잔 하십시다.","허허, 졌사옵니다. 산은 도망가지 않사옵니다."],art:["ambush","산 주인이 이른다! 바위 뒤에서 일어나 넘어오는 놈을 막아라!"],recorded:!0,male:!0},"daegaya-ruler":{voice:"Umbriel",style:"예순여섯의 그윽하고 경건한 임금. 후덕하고 느린 노인의 목소리로, 조상께 아뢰듯 말한다.",tap:["조상께 여쭙고 왔사옵니다.","말씀하소서.","가락이 고운 날이옵니다."],obey:["조상께 여쭙고 행하겠사옵니다.","가락에 맞추어 천천히 해내겠사옵니다.","뜻을 받들겠사옵니다."],auto:["조상께서 이 싸움을 맡아 주실 것이옵니다!","북과 현이 울린다! 가락에 맞춰 나아가라!","조상이 굽어보신다! 물러서지 마라!","조상께서 도우셨사옵니다.","가락이 어긋났사옵니다. 다시 고르겠사옵니다."],art:["rite","조상이시여, 굽어보소서! 가락에 맞춰 적을 물리치소서!"],recorded:!0,male:!0},"dm-buyeo-1":{voice:"Brio",style:"마흔넷의 거침없고 호쾌한 부여 마가. 시원하고 힘찬 장수의 목소리로, 말을 몰듯 말한다.",tap:["말은 안장을 얹었사옵니다.","부르셨사옵니까.","예, 여기 있사옵니다."],obey:["말 위에서 해내겠사옵니다.","바람처럼 다녀오겠사옵니다.","맡겨 주소서!"],auto:["말머리가 향하는 곳이 싸움터이옵니다!","말을 몰아라! 앞서 달려라!","짓밟고 지나가라!","이겼사옵니다. 말에게 먹이를 주겠사옵니다.","말이 지쳤사옵니다. 다시 달리겠사옵니다."],art:["vanguard","말을 몰아라! 부여의 마가가 앞서 달린다!"],recorded:!0,male:!0},"dm-buyeo-2":{voice:"Lora",style:"스물셋의 밝고 날랜 부여 사냥꾼. 맑고 시원한 목소리로, 활기차게 말한다.",tap:["부르셨사옵니까!","숲에서 오는 길이옵니다.","말씀하소서."],obey:["짐승 잡듯 해내겠사옵니다.","사냥이라면 맡겨 주소서.","곧 다녀오겠사옵니다."],auto:["사냥은 제가 맡겠사옵니다!","쫓아라! 사슴 몰듯 몰아라!","겨누어라! 놓치지 마라!","잡았사옵니다! 큰 사냥이었사옵니다.","놓쳤사옵니다. 다시 쫓겠사옵니다."],art:["snipe","큰 짐승을 잡듯 쏜다! 적장을 겨누어라!"],recorded:!0},"dm-daemusin":{voice:"Sadachbia",style:"열아홉의 슬기롭고 대담한 젊은 왕. 맑고 단단한 청년의 목소리로, 묻고 헤아린 뒤 정하듯 말한다.",tap:["부르셨소.","말씀하시오.","예, 듣고 있소."],obey:["길을 먼저 보고 하겠소.","맡겨 주시오. 해내겠소.","뜻을 받들겠소."],auto:["이 싸움은 내가 맡겠소!","길을 먼저 보라! 그리고 나아간다!","물러서지 마라! 고구려의 이름으로!","이겼소. 길이 열렸소.","졌소. 길을 다시 보겠소."],art:["sway","칼을 거두어라! 길을 먼저 보고, 나와 함께 가자!"],recorded:!0,male:!0},"dm-daeso":{voice:"Charon",style:"일흔 넘은 오만하고 의심 많은 늙은 왕. 위엄 있고 쉰 듯한 노인의 목소리로, 아랫사람을 굽어보듯 말한다.",tap:["무슨 일인가.","말해 보게.","나를 부르는가."],obey:["내가 직접 해 주겠네.","지켜보게. 부여의 왕이 어떤 것인지.","그리하겠네."],auto:["이 싸움은 내가 맡겠네!","부여의 군사들아! 앞으로!","감히 누구 앞에서! 밀어라!","당연하네. 내가 이겼네.","이럴 리가 없네! 물러난다!"],art:["vanguard","길을 열어라! 늙었어도 부여의 왕이다, 내가 앞선다!"],recorded:!0,male:!0},"dm-gwaeyu":{voice:"Bodi",style:"서른의 우직하고 겁 없는 거인. 크고 우렁찬 사내의 목소리로, 짧고 굵게 말한다.",tap:["예!","여기 있사옵니다.","무엇을 베오리까."],obey:["베고 오겠사옵니다!","머리를 가져오라 하시면 가져오겠사옵니다.","맡겨 주소서!"],auto:["제가 가겠사옵니다!","두려워 마라! 내 뒤에 서라!","베어라! 앞을 막으면 다 벤다!","베었사옵니다!","쓰러뜨리지 못했사옵니다. 다시 가겠사옵니다!"],art:["vanguard","환두대도가 간다! 길을 열어라!"],recorded:!0,male:!0},"dm-maro":{voice:"Daro",style:"서른넷의 말수 적고 길눈 밝은 산사람. 투박하고 낮은 사내의 목소리로, 무뚝뚝하게 말한다.",tap:["예.","길은 보았사옵니다.","말씀하소서."],obey:["길을 앞서 열겠사옵니다.","따라오소서.","다녀오겠사옵니다."],auto:["길은 제가 아옵니다!","산길로 돌아라! 소리 내지 마라!","내 뒤만 따라와라!","길이 맞았사옵니다.","길이 막혔사옵니다. 돌아가겠사옵니다."],art:["ambush","산길로 돌아라! 적의 등 뒤를 친다!"],recorded:!0,male:!0},"dm-mir":{voice:"Laomedeia",style:"스물셋의 밝고 날랜 졸본의 여궁수. 맑고 청량한 젊은 여인의 목소리로, 씩씩하게 말한다.",tap:["부르셨사옵니까!","졸본은 제가 지키고 있사옵니다.","활은 당겨 두었사옵니다."],obey:["날래게 다녀오겠사옵니다.","한 살로 끝내겠사옵니다.","맡겨 주소서!"],auto:["졸본의 활이 맡겠사옵니다!","겨누어라! 우리 도읍에 발 들이게 마라!","쏘아라! 한 발도 아끼지 마라!","이겼사옵니다! 졸본은 무사하옵니다.","송구하옵니다. 다시 활을 매겠사옵니다."],art:["snipe","옛 도읍에 발을 들였다! 적장을 겨누어 쏘아라!"],recorded:!0},"dokro-1":{voice:"Aoede",style:"서른의 대담하고 실속 있는 여선장. 다부지고 맑은 여장부의 목소리로, 당차게 말하되 예는 지킨다.",tap:["바다에선 제가 우두머리이옵니다.","품삯은 정해 두었사옵니까.","예, 부르셨사옵니까."],obey:["품삯만큼은 해내겠사옵니다.","배를 대 놓겠사옵니다.","바다에선 틀림이 없사옵니다."],auto:["바다에선 제가 맡겠사옵니다!","뱃전을 붙여라! 올라타라!","닻줄을 끊어라! 놓치지 마라!","이겼사옵니다. 몫은 나누어 주겠사옵니다.","물때가 틀렸사옵니다. 다시 나가겠사옵니다."],art:["ambush","닻을 내려라! 숨은 배들아, 한꺼번에 뱃전을 들이받아라!"],recorded:!0},"dokro-ruler":{voice:"Gero",style:"마흔다섯의 수완 좋고 능청스러운 장사꾼. 매끄러운 중년 사내의 목소리로, 웃음기를 머금고 말한다.",shoutStyle:"마흔다섯의 수완 좋은 사내. 매끄러운 중년의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예, 부르셨사옵니까.","크게 불어날 이야기이옵니까.","무슨 일이시옵니까."],obey:["이문이 남게 해 오겠사옵니다.","크게 불어나지요. 맡겨 주소서.","나눌 것은 나누고 해내겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","앞을 막는 값은 곱절로 받는다! 밀어붙여라!","흔들리지 마라! 불어나는 건 우리다!","크게 불어났사옵니다. 이겼사옵니다.","밑지는 장사였사옵니다. 다시 셈하겠사옵니다."],art:["sway","칼을 거두어라! 우리 편에 서면 크게 불어난다!"],recorded:!0,male:!0},"dongokjeo-1":{voice:"Zeno",style:"예순둘의 묵직하고 끈기 있는 늙은 어부 우두머리. 낮고 느린 노인의 목소리로, 한마디로 끝내듯 말한다.",tap:["예.","그물은 말려 두었사옵니다.","말씀하소서."],obey:["돌은 구르지 않사옵니다. 맡겨 주소서.","물때를 기다려 하겠사옵니다.","그리하겠사옵니다."],auto:["돌처럼 버티겠사옵니다!","그물을 던져라! 빠져나가지 못하게!","버텨라! 물러서면 쓸려 간다!","끝났사옵니다. 그물을 걷겠사옵니다.","그물이 찢어졌사옵니다. 다시 깁겠사옵니다."],art:["ambush","그물을 펼쳐라! 걸려든 놈을 한꺼번에 끌어내라!"],recorded:!0,male:!0},"eumjeup-ruler":{voice:"Umbriel",style:"마흔넷의 푸근하고 넉넉한 살림꾼. 후덕한 사내의 목소리로, 호리병을 권하듯 정겹게 말한다.",tap:["한 모금 하시겠사옵니까.","허허, 왔사옵니다.","부르셨사옵니까."],obey:["백성 배부르게 해 놓겠사옵니다.","허허, 맡겨 주소서.","넉넉히 챙겨 두겠사옵니다."],auto:["곳간 걱정은 마라! 힘껏 싸워라!","배불리 먹었다! 밀어붙여라!","한 모금 마시고 나아가라!","허허, 이겼사옵니다. 한 모금 하시지요.","허허, 졌사옵니다. 그래도 곳간은 남았사옵니다."],art:["shout","곳간은 가득하다! 한 모금 마시고 함성을 올려라!"],recorded:!0,male:!0},"gammun-1":{voice:"Riko",style:"서른일곱의 참을성 있고 소박한 사내. 담담하고 차분한 목소리로, 서두르지 않고 말한다.",tap:["예, 듣고 있사옵니다.","기다리고 있었사옵니다.","말씀하소서."],obey:["익을 때까지 기다리면 되옵니다.","서두르지 않고 해내겠사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","서두르지 마라! 때가 올 때까지 버텨라!","자리를 지켜라! 흔들리지 마라!","익었사옵니다. 이겼사옵니다.","덜 익었사옵니다. 다시 기다리겠사옵니다."],art:["order","버텨라! 때가 무르익을 때까지 한 발도 물러서지 마라!"],recorded:!0,male:!0},"gampyeong-ruler":{voice:"Algieba",style:"마흔셋의 소탈하고 밝은 사람. 정겹고 푸근한 중년 사내의 목소리로, 허허 웃으며 말한다.",tap:["허허, 왔사옵니다.","물때를 보고 오는 길이옵니다.","말씀하소서."],obey:["진흙 속에서도 길은 찾사옵니다.","허허, 맡겨 주소서.","물때 맞춰 해내겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","갯벌로 끌어들여라! 발이 빠지면 친다!","물때를 놓치지 마라! 밀어붙여라!","허허, 이겼사옵니다. 물때가 좋았사옵니다.","허허, 졌사옵니다. 물이 들면 또 길이 나오옵니다."],art:["ambush","갯벌로 끌어들여라! 발이 빠진 놈들을 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"geonma-1":{voice:"Algenib",style:"마흔둘의 성급하고 용맹한 기병. 기세 좋은 사내의 목소리로, 선봉에 서고 싶어 안달하듯 말한다.",tap:["예! 말씀하소서.","말은 달릴 준비가 되었사옵니다.","무엇이든 맡기소서!"],obey:["선봉은 제가 서겠사옵니다!","달려가 먼저 닿겠사옵니다.","기다릴 수 없사옵니다. 바로 가겠사옵니다!"],auto:["선봉은 제 몫이옵니다!","말발굽 소리가 곧 북이다! 달려라!","앞서 달려라! 짓밟고 지나가라!","가장 먼저 닿았사옵니다!","너무 앞서 나갔사옵니다. 다시 달리겠사옵니다."],art:["vanguard","말발굽이 북이다! 내 뒤를 따라 단숨에 달려라!"],recorded:!0,male:!0},"geonma-ruler":{voice:"Callirrhoe",style:"서른둘의 어질고 포근한 우두머리. 부드럽고 단정한 목소리로, 굳은 심지를 품고 말한다.",tap:["부르셨사옵니까.","곁에 있사옵니다.","말씀하소서."],obey:["백성이 굶지 않게 하겠사옵니다.","정성껏 해내겠사옵니다.","염려 마소서. 맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","백성의 곳간을 지켜라! 물러서지 마라!","힘을 내라! 함께 돌아가자!","모두 무사하니 다행이옵니다.","송구하옵니다. 다시 곳간부터 채우겠사옵니다."],art:["shout","굶는 이 없게 하리라! 함께 힘을 내라, 함성을 올려라!"],recorded:!0},"gj-adogan":{voice:"Enzo",style:"쉰여섯의 신중한 맏이. 느릿하고 인자한 어른의 목소리로, 앞장서 노래하자고 이끌듯 말한다.",tap:["왔소이다.","말씀하시오.","허허, 부르셨소."],obey:["신중히 해 보겠소.","모두와 뜻을 모아 하겠소.","그리하겠소이다."],auto:["이 싸움은 내가 맡겠소!","노래하라! 소리를 모아 나아가라!","다 함께다! 흩어지지 마라!","허허, 이겼소. 노래를 부릅시다.","졌소이다. 뜻을 다시 모읍시다."],art:["shout","목청을 모아라! 구지의 노래로 함성을 올려라!"],recorded:!0,male:!0},"gj-musoe":{voice:"Cruz",style:"서른여덟의 우직하고 충직한 쇠둑 우두머리. 투박하고 단단한 사내의 목소리로, 말보다 망치로 대답하듯 말한다.",tap:["예.","쇠는 거짓말을 안 하옵니다.","망치 들고 왔사옵니다."],obey:["쇠가 하는 말을 믿으소서. 해내겠사옵니다.","두드려서 만들어 보이겠사옵니다.","맡겨 주소서."],auto:["쇠가 맡겠사옵니다!","덩이쇠를 들어라! 앞을 부숴라!","망치질하듯 밀어붙여라!","쇠는 거짓말을 안 하옵니다. 이겼사옵니다.","쇠가 덜 달았사옵니다. 다시 두드리겠사옵니다."],art:["vanguard","덩이쇠를 들어라! 망치가 앞장선다!"],recorded:!0,male:!0},"gj-ocheongan":{voice:"Milo",style:"마흔다섯의 강굽이 뱃사공. 차분하되 기운이 센 중년 사내의 목소리로 말한다.",tap:["예, 뱃줄은 매어 두었사옵니다.","부르셨사옵니까.","강물이 사납사옵니다. 말씀하소서."],obey:["강굽이는 제 손바닥이옵니다.","건네 드리겠사옵니다.","노를 잡고 해내겠사옵니다."],auto:["강굽이는 제가 맡겠사옵니다!","노를 저어라! 굽이 뒤에서 치고 나가라!","배를 붙여라! 뛰어올라라!","건넜사옵니다. 이겼사옵니다.","강물이 거슬렀사옵니다. 다시 건너겠사옵니다."],art:["ambush","강굽이에 숨은 배들아, 한꺼번에 나와 옆구리를 들이쳐라!"],recorded:!0,male:!0},"gj-odogan":{voice:"Gero",style:"마흔넷의 셈 빠르고 싹싹한 장사꾼. 매끄러운 사내의 목소리로, 웃으며 값을 부르듯 말한다.",shoutStyle:"마흔넷의 장사꾼. 매끄러운 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예, 부르셨사옵니까.","값은 후하게 쳐 드리겠사옵니다.","무슨 일이시옵니까."],obey:["셈이 맞게 해 오겠사옵니다.","웃으며 다녀오겠사옵니다.","값은 제가 부르옵니다. 맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","값을 치르게 하라! 밀어붙여라!","밀리지 마라! 셈은 우리가 한다!","장사가 잘되었사옵니다. 이겼사옵니다.","밑지는 셈이었사옵니다. 다시 값을 매기겠사옵니다."],art:["sway","값을 쳐 주겠다! 칼을 거두고 우리 편에 서라!"],recorded:!0,male:!0},"gj-pidogan":{voice:"Algenib",style:"마흔의 고집 센 산사람. 거칠고 단단한 사내의 목소리로, 짧게 잘라 말한다.",tap:["예.","산에서 내려왔사옵니다.","무슨 일이옵니까."],obey:["한번 정한 건 바꾸지 않사옵니다.","산길로 다녀오겠사옵니다.","맡겨 주소서."],auto:["산이 맡겠사옵니다!","고개로 올라붙어라! 아래로 쓸어라!","버텨라! 한 발도 못 넘긴다!","끝났사옵니다. 산으로 돌아가겠사옵니다.","산이 무너졌사옵니다. 다시 오르겠사옵니다."],art:["ambush","고개 위에서 돌을 굴려라! 기어오르는 놈을 쳐라!"],recorded:!0,male:!0},"gj-sincheongan":{voice:"Rina",style:"서른셋의 신비롭고 당찬 무녀. 맑고 또렷하며 강단 있는 목소리로, 하늘에 고하듯 말한다.",tap:["제를 올리던 중이옵니다.","말씀하소서.","하늘이 이르시기를, 부르셨사옵니다."],obey:["하늘의 뜻을 받들어 행하겠사옵니다.","제를 올려 길을 열겠사옵니다.","맡겨 주소서. 하늘이 도우실 것이옵니다."],auto:["하늘이 이 싸움을 맡으셨사옵니다!","두려워 마라! 하늘이 굽어보신다!","방울을 울려라! 신령을 부른다!","하늘이 도우셨사옵니다.","정성이 모자랐사옵니다. 다시 제를 올리겠사옵니다."],art:["rite","하늘이시여, 이 땅의 적을 물리쳐 주소서! 방울을 울려라!"],recorded:!0},"gj-singwigan":{voice:"Nyla",style:"스물아홉의 물질하는 시원시원한 여인. 맑고 또랑또랑한 목소리로, 막힘없이 말한다.",tap:["예, 물에서 막 나왔사옵니다.","부르셨사옵니까.","말씀하소서."],obey:["물속이라면 맡겨 주소서.","숨 한 번에 다녀오겠사옵니다.","시원하게 해내겠사옵니다."],auto:["물질은 제가 맡겠사옵니다!","숨을 참아라! 물밑으로 들어가라!","솟구쳐라! 한꺼번에 덮쳐라!","건져 올렸사옵니다! 이겼사옵니다.","숨이 모자랐사옵니다. 다시 들어가겠사옵니다."],art:["ambush","숨 한 번에 물밑으로! 솟구쳐 한꺼번에 덮쳐라!"],recorded:!0},"gj-suro":{voice:"Elio",style:"열여섯의 앳되지만 침착한 소년 왕. 맑고 단정한 소년의 목소리로, 하늘의 무게를 실어 느리고 차분하게 말한다.",tap:["부르셨소.","말씀하시오.","듣고 있소."],obey:["받아들이겠소.","하늘이 정한 대로 하겠소.","그리하겠소."],auto:["이 싸움은 내가 맡겠소!","하늘이 보고 계시오! 나아가라!","다투지 말고 맞서라! 흔들리지 마라!","이겼소. 하늘이 도우셨소.","졌소. 바다는 다시 차오르는 법이오."],art:["sway","칼을 거두어라! 하늘이 낸 사람이 부른다, 함께 가자!"],recorded:!0,male:!0},"gj-tahae":{voice:"Achird",style:"스물다섯의 꾀 많고 자신만만한 젊은 장수. 매서운 청년의 목소리로, 비꼬듯 웃으며 말한다.",shoutStyle:"스물다섯의 꾀 많은 젊은 장수. 매서운 청년의 목소리지만 싸움에서는 비꼼 없이 날카롭고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["부르셨소?","재미있는 일이오?","말씀해 보시오."],obey:["둔갑으로 겨뤄 보겠소?","꾀로 이기고 오겠소.","맡겨 보시오. 후회는 없을 것이오."],auto:["이 싸움은 내가 맡겠소!","꾀로 돌려라! 정면은 내가 연다!","날뛰어라! 저들이 당황할 때까지!","이겼소. 꾀가 힘을 이겼소.","졌소. 깨끗이 엎드리고 다른 길로 가겠소."],art:["vanguard","숫돌에 갈린 칼이다! 내 뒤를 따라 단숨에 뚫어라!"],recorded:!0,male:!0},"gj-tahae-1":{voice:"Callirrhoe",style:"서른의 의리 있고 시원한 배 모는 여인. 맑고 힘 있는 목소리로, 거침없이 말한다.",tap:["예, 배는 띄워 두었사옵니다.","부르셨사옵니까.","말씀하소서."],obey:["의리는 지키옵니다. 맡겨 주소서.","키를 잡고 해내겠사옵니다.","배를 몰아 다녀오겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","배를 붙여라! 의리로 뛰어올라라!","돛을 올려라! 뒤처지는 놈 없이 가자!","이겼사옵니다. 모두 배에 오르소서.","배가 기울었사옵니다. 다시 띄우겠사옵니다."],art:["ambush","돛을 내리고 숨어라! 가까이 오면 뛰어올라 덮쳐라!"],recorded:!0},"gj-yeodogan":{voice:"Sadaltager",style:"마흔여덟의 수더분한 농사꾼. 투박하고 정겨운 사내의 목소리로, 곡식부터 헤아리듯 말한다.",tap:["예, 밭에서 오는 길이옵니다.","곡식은 넉넉하옵니다.","무슨 일이옵니까."],obey:["곡식 셈부터 해 놓고 하겠사옵니다.","수더분하게 해 보겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","쟁기를 들었던 손이다! 밀어붙여라!","곡식을 지켜라! 한 줌도 내주지 마라!","이겼사옵니다. 곡식 셈을 해 보겠사옵니다.","졌사옵니다. 올해 곡식이 아깝사옵니다."],art:["order","곡식을 지켜라! 줄을 맞춰 한 걸음씩 밀어라!"],recorded:!0,male:!0},"gj-yusugan":{voice:"Daro",style:"서른일곱의 무뚝뚝한 강사람. 낮고 담백한 사내의 목소리로, 말을 아낀다.",tap:["예.","강에서 왔사옵니다.","말씀하소서."],obey:["받들겠사옵니다.","강을 따라 다녀오겠사옵니다.","맡겨 주소서."],auto:["강물이 맡겠사옵니다!","물을 타라! 소리 없이 다가가라!","놓치지 마라!","끝났사옵니다.","물이 막혔사옵니다. 다시 돌아가겠사옵니다."],art:["ambush","강물을 타고 숨어들어라! 물가에서 덮쳐라!"],recorded:!0,male:!0},"goguryeo-1":{voice:"Brio",style:"마흔일곱의 위압감 있고 자부심 강한 귀족 무장. 위엄 있고 힘찬 사내의 목소리로 말한다.",tap:["부르셨사옵니까.","도끼는 들고 있사옵니다.","말씀하소서."],obey:["귀족의 이름을 걸고 해내겠사옵니다.","맡겨 주소서. 앞서겠사옵니다.","명을 받들겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","도끼를 들어라! 귀족이 앞선다!","밀어붙여라! 한 치도 물러서지 마라!","이겼사옵니다. 당연한 일이옵니다.","물러나옵니다. 이 빚은 갚겠사옵니다."],art:["ambush","숲에 숨어라! 내 도끼가 오르면 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"goguryeo-ruler":{voice:"Charon",style:"쉰 살의 위엄 있고 엄격한 대왕. 무겁고 울림 있는 사내의 목소리로, 쉽게 고개 숙이지 않는 기개로 말한다.",tap:["말씀하시오.","듣고 있소.","무슨 일이시오."],obey:["고구려의 이름으로 해내겠소.","맡은 일은 어김없이 하겠소.","그리하겠소."],auto:["이 싸움은 내가 맡겠소!","고구려의 활이다! 겨누어라!","한 발도 물러서지 마라!","이겼소. 이것이 고구려요.","졌소. 이 빚은 반드시 갚겠소."],art:["snipe","옛 땅을 되찾는 화살이다! 적장의 가슴을 꿰뚫어라!"],recorded:!0,male:!0},"goja-1":{voice:"Mako",style:"마흔하나의 호탕하고 낙천적인 뱃사공. 투박하고 시원한 사내의 목소리로, 말끝을 크게 올려 웃으며 말한다.",shoutStyle:"마흔하나의 뱃사공. 투박한 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예! 왔사옵니다!","파도가 좋사옵니다!","부르셨습지요!"],obey:["파도가 사나울수록 노가 가볍습지요!","배는 제가 몰겠사옵니다!","맡겨 주소서!"],auto:["파도 위에서는 제가 맡겠사옵니다!","노를 저어라! 파도를 타라!","배를 붙여라! 올라타라!","이겼습지요! 한 잔 합시다!","파도가 셌습지요. 다시 나가겠사옵니다."],art:["ambush","돛을 내려라! 파도 뒤에서 튀어나와 뱃전을 들이받아라!"],recorded:!0,male:!0},"golbeol-1":{voice:"Algieba",style:"쉰둘의 노회하고 몸을 사리는 늙은 병사. 퉁명스럽고 메마른 사내의 목소리로, 빼듯 말한다.",tap:["예, 예. 왔사옵니다.","목숨이 하나뿐이라서 말이옵니다.","무슨 일이옵니까."],obey:["목숨이 하나뿐이지만 그래도 하겠사옵니다.","뒤에서 살펴 가며 하겠사옵니다.","시키시면 해야지요."],auto:["정 그렇다면 제가 맡겠사옵니다!","몸을 낮춰라! 살아서 돌아가자!","뒤처지지 마라! 죽기는 싫지 않으냐!","살았사옵니다. 이겼으니 됐사옵니다.","그럴 줄 알았사옵니다. 목숨부터 챙기옵니다."],art:["ambush","엎드려라! 목숨이 아깝거든 숨었다가 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"golbeol-ruler":{voice:"Jori",style:"스물여덟의 야성 넘치는 여사냥꾼. 맑고 당돌한 목소리로, 웃음을 섞은 위협처럼 말한다.",tap:["먹잇감이 있사옵니까.","부르셨사옵니까.","예, 여기 있사옵니다."],obey:["먹잇감만 알려 주소서.","날쌔게 다녀오겠사옵니다.","살림은 모르옵니다. 싸움이라면 맡겨 주소서."],auto:["먹잇감은 제가 맡겠사옵니다!","이리 떼처럼 덮쳐라!","한 놈도 놓치지 마라! 물어라!","잡았사옵니다. 좋은 먹잇감이었사옵니다.","놓쳤사옵니다. 다음 사냥은 다를 것이옵니다."],art:["ambush","발톱을 세워라! 먹잇감이 지나가면 한꺼번에 물어라!"],recorded:!0},"goryong-1":{voice:"Arlo",style:"쉰여섯의 사납고 노련한 산 장수. 낮고 가라앉은 중년 사내의 목소리로, 말수 적게 무겁게 말한다.",tap:["예.","산에서 내려왔사옵니다.","말씀하소서."],obey:["산을 타듯 해내겠사옵니다.","범은 한번 문 것을 놓지 않사옵니다.","맡겨 주소서."],auto:["산이 맡겠사옵니다!","능선을 타라! 아래로 덮쳐라!","숨죽여라! 때를 기다려라!","끝났사옵니다. 산으로 돌아가겠사옵니다.","범도 덫에 걸리옵니다. 다시 산을 타겠사옵니다."],art:["ambush","능선 뒤에서 범처럼 뛰쳐나가라! 앞장서 물어뜯어라!"],recorded:!0,male:!0},"goryong-ruler":{voice:"Sulafat",style:"스물여섯의 넉살 좋고 풍류를 아는 사교가. 맑고 상냥한 목소리로 웃음을 섞어, 가볍게 놀려도 선은 지키며 말한다.",tap:["예, 부르셨사옵니까.","한 잔 받으시지요.","웃으며 듣고 있사옵니다."],obey:["잔 기울일 새 해 놓겠사옵니다.","웃으며 다녀오겠사옵니다.","맡겨 주소서. 한 잔 받으시지요."],auto:["이 싸움은 제가 맡겠사옵니다!","잔을 내려놓아라! 이제 나아갈 때다!","웃으며 밀어붙여라!","이겼사옵니다. 한 잔 받으시지요.","졌사옵니다. 술이 쓰옵니다."],art:["sway","칼을 거두고 잔을 받으시오! 우리와 함께 가자!"],recorded:!0},"gosaburi-1":{voice:"Achird",style:"서른넷의 눈썰미 좋고 침착한 사내. 또렷하고 날 선 청년의 목소리로, 짧게 말한다.",tap:["예, 보고 있사옵니다.","말씀하소서.","빈틈은 찾아 두었사옵니다."],obey:["빈틈을 찾아 쪼겠사옵니다.","침착하게 해내겠사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","빈틈을 찾아라! 보이면 쪼아라!","서두르지 마라! 한 곳만 파라!","빈틈이 있었사옵니다. 이겼사옵니다.","빈틈이 없었사옵니다. 물러서옵니다."],art:["feint","물러서는 척하라! 빈틈이 보이면 단숨에 쪼아라!"],recorded:!0,male:!0},"gosaburi-2":{voice:"Zuri",style:"스물둘의 쾌활하고 자유로운 처녀. 밝고 통통 튀는 목소리로, 막힘없이 말한다.",tap:["예! 부르셨사옵니까!","바람이 좋사옵니다!","여기 있사옵니다!"],obey:["날아가듯 다녀오겠사옵니다!","갈매기처럼 가볍게 해내겠사옵니다.","맡겨 주소서!"],auto:["이 싸움은 제가 맡겠사옵니다!","돛을 펴라! 바람을 타고 덮쳐라!","날아올라라! 한꺼번에 내리꽂아라!","이겼사옵니다! 하늘이 맑았사옵니다.","날개가 젖었사옵니다. 다시 날겠사옵니다."],art:["ambush","돛을 접고 숨었다가 갈매기처럼 한꺼번에 내리덮쳐라!"],recorded:!0},"gosaburi-ruler":{voice:"Nyla",style:"스물여덟의 신중하고 영리한 우두머리. 차분하고 은근한 목소리로, 때를 읽으며 말한다.",tap:["말씀하소서.","바람이 어디서 부는지 보고 있사옵니다.","부르셨사옵니까."],obey:["때를 보아 움직이겠사옵니다.","서두르지 않고 해내겠사옵니다.","바람이 바뀌었사옵니다. 바로 하겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","때를 기다려라! 바람이 돌면 친다!","흩어지지 마라! 신호를 기다려라!","바람이 우리 쪽으로 불었사옵니다.","바람이 바뀌었사옵니다. 물러나옵니다."],art:["feint","물러나라! 바람이 돌아서면 그때 덮쳐라!"],recorded:!0},"guga-ruler":{voice:"Leda",style:"열아홉의 다정하고 순한 처녀. 맑고 조곤조곤한 목소리로, 마음을 헤아리듯 말한다.",tap:["예, 부르셨사옵니까.","이 아이도 같이 왔사옵니다.","말씀하소서."],obey:["마음을 잘 살펴서 하겠사옵니다.","이 아이와 함께 다녀오겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","해치지 마라! 마음을 읽고 맞서라!","두려워 마라! 이 아이들이 곁에 있다!","다치는 이 없이 끝나서 다행이옵니다.","송구하옵니다. 마음을 더 읽고 오겠사옵니다."],art:["sway","칼을 거두어라! 짐승도 사람도 마음은 같다, 우리와 함께 가자!"],recorded:!0},"guya-2":{voice:"Rami",style:"서른넷의 먹성 좋고 유쾌한 거구. 우렁차고 투박한 사내의 목소리로, 크게 웃으며 먹는 이야기를 섞어 말한다.",shoutStyle:"서른넷의 거구. 우렁찬 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["크하하! 왔사옵니다.","고기는 있사옵니까!","부르셨사옵니까."],obey:["고기만 넉넉히 주시면 도끼로 갚겠사옵니다!","배부르면 못 할 일이 없사옵니다.","크하하! 맡겨 주소서."],auto:["배가 찼사옵니다! 제가 맡겠사옵니다!","고기 냄새 난다! 밀어붙여라!","도끼로 쪼개라! 한 놈도 놓치지 마라!","크하하! 이겼으니 잔치이옵니다!","배가 고파서 졌사옵니다. 먹고 다시 가겠사옵니다."],art:["vanguard","밥값은 도끼로 한다! 내 뒤를 따라 돌격하라!"],recorded:!0,male:!0},"guya-ruler":{voice:"Milo",style:"마흔여덟의 장인다운 자부심과 뚝심을 지닌 쇠 나라 우두머리. 굵고 너그러운 사내의 목소리로 말한다.",tap:["허허, 왔사옵니다.","쇠는 달궈져 있사옵니다.","말씀하소서."],obey:["쇠를 다루듯 차근히 하겠사옵니다.","단단히 벼려 놓겠사옵니다.","맡겨 주소서. 뚝심으로 해내겠사옵니다."],auto:["쇠 나라의 우두머리가 맡겠사옵니다!","방패를 이어 붙여라! 한 덩이로 밀어라!","대열을 쇠처럼 굳혀라! 틈을 주지 마라!","잘 벼려졌사옵니다. 이겼사옵니다.","쇠도 식으면 깨지옵니다. 다시 달구겠사옵니다."],art:["order","방패를 이어 붙여라! 쇠처럼 한 덩이로 나아간다!"],recorded:!0,male:!0},"gwanna-1":{voice:"Charon",style:"서른여섯의 엄격하고 묵묵한 훈련 대장. 굳고 짧은 사내의 목소리로 말한다.",tap:["예.","대기하고 있사옵니다.","명을 내리소서."],obey:["명대로 하겠사옵니다.","군사와 함께 두드려 놓겠사옵니다.","받들겠사옵니다."],auto:["제가 맡겠사옵니다!","대열을 지켜라! 흐트러지면 맞는다!","두드려라! 쇠처럼 버텨라!","단련한 보람이 있었사옵니다.","단련이 부족했사옵니다. 다시 두드리겠사옵니다."],art:["vanguard","쇠처럼 두들겨라! 단련한 대로 밀고 들어간다!"],recorded:!0,male:!0},"gwanna-ruler":{voice:"Cruz",style:"마흔넷의 강골에 완고한 우두머리. 묵직하게 가라앉은 사내의 목소리로, 웃음 없이 말한다.",tap:["말씀하소서.","쇠는 식지 않았사옵니다.","여기 있사옵니다."],obey:["쇠는 휘어도 꺾이지 않사옵니다.","버티는 일이라면 맡겨 주소서.","그리하겠사옵니다."],auto:["쇠가 맡겠사옵니다!","꺾이지 마라! 쇠처럼 버텨라!","불길 속에서도 물러서지 마라!","끝났사옵니다. 쇠는 꺾이지 않았사옵니다.","꺾였사옵니다. 다시 불에 달구겠사옵니다."],art:["order","쇠처럼 버텨라! 한 걸음도 물러서지 말고 진을 굳혀라!"],recorded:!0,male:!0},"haseulla-1":{voice:"Koda",style:"스물아홉의 밝고 날랜 자신만만한 기마 궁수. 맑고 시원한 청년의 목소리로, 활기차게 말한다.",tap:["예! 부르셨사옵니까.","말은 준비되었사옵니다!","활도 준비되었사옵니다."],obey:["말 위에서 쏘고 오겠사옵니다.","바람처럼 다녀오겠사옵니다.","맡겨 주소서!"],auto:["이 싸움은 제 활에 맡기소서!","달리며 쏘아라! 멈추지 마라!","말을 몰아라! 쏘며 앞서라!","이겼사옵니다! 말도 활도 멀쩡하옵니다.","말이 지쳤사옵니다. 다시 달리겠사옵니다."],art:["snipe","말 위에서 쏜다! 내 살은 달리는 말보다 빠르다!"],recorded:!0,male:!0},"haseulla-ruler":{voice:"Sola",style:"스물여섯의 매서운 자부심의 여궁수. 맑고 단단한 당찬 목소리로, 한번 겨눈 곳은 끝까지 겨누듯 말한다.",tap:["예, 듣고 있사옵니다.","활은 당겨 두었사옵니다.","이 활이 말하옵니다. 명하소서."],obey:["겨눈 곳은 끝까지 쏘겠사옵니다.","이 활이 대답하겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제 활이 맡겠사옵니다!","겨누어라! 한번 정한 곳은 놓치지 마라!","쏘아라! 한 발씩, 정확히!","이겼사옵니다. 활이 말했사옵니다.","송구하옵니다. 다시 시위를 매겠사옵니다."],art:["snipe","단궁이 운다! 한번 겨눈 적장은 놓치지 않는다!"],recorded:!0},"hwanna-1":{voice:"Elio",style:"스물다섯의 밝고 성실한 젊은 사공. 밝고 힘찬 청년의 목소리로, 건네 주겠다는 듯 씩씩하게 말한다.",tap:["예! 부르셨사옵니까.","큰 강은 제 마당이옵니다.","말씀하소서!"],obey:["건네 드리겠사옵니다.","물을 건너 다녀오겠사옵니다.","맡겨 주소서!"],auto:["이 싸움은 제가 맡겠사옵니다!","강을 건너라! 저들 뒤로 돌아라!","뗏목을 붙여라! 한꺼번에 건너 덮쳐라!","건넜사옵니다! 이겼사옵니다.","물이 불었사옵니다. 다시 건너겠사옵니다."],art:["ambush","뗏목을 밀어라! 강을 건너 저들 등 뒤를 덮쳐라!"],recorded:!0,male:!0},"iseo-ruler":{voice:"Erinome",style:"스물둘의 신중하고 사려 깊은 처녀. 조용하고 정중한 맑은 목소리로, 헤아리듯 차분히 말한다.",tap:["예, 듣고 있사옵니다.","헤아려 보고 있었사옵니다.","말씀하소서."],obey:["헤아려 보건대 할 수 있사옵니다.","차분히 살펴 해내겠사옵니다.","맡겨 주소서."],auto:["헤아려 보니 제가 맡을 만하옵니다!","당황하지 마라! 헤아린 대로 나아간다!","힘을 모아라! 함께 가면 이긴다!","헤아린 대로 되었사옵니다.","헤아림이 모자랐사옵니다. 다시 셈하겠사옵니다."],art:["shout","헤아림은 끝났다! 모두 힘을 모아 함성을 올려라!"],recorded:!0},"jeoga-ruler":{voice:"Bodi",style:"서른여덟의 저돌적이고 호쾌한 힘센 사내. 우렁찬 목소리로, 생각보다 몸이 먼저 나가듯 말한다.",shoutStyle:"서른여덟의 힘센 사내. 우렁찬 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["크하하! 왔사옵니다.","들이받을 데가 있사옵니까!","말씀하소서!"],obey:["들이받겠사옵니다!","힘이라면 맡겨 주소서!","크하하! 바로 가겠사옵니다."],auto:["들이받겠사옵니다!","밀어라! 앞을 부수고 나가라!","멈추지 마라! 부딪쳐라!","크하하! 부수었사옵니다!","너무 힘만 썼사옵니다. 다시 들이받겠사옵니다."],art:["ambush","멧돼지처럼 숲에서 튀어나와라! 한 덩이로 들이받아라!"],recorded:!0,male:!0},"jm-haengin-ruler":{voice:"Neno",style:"예순셋의 엄격하고 노련한 늙은 군장. 무겁고 느린 노인의 목소리로, 나라 잃은 한을 삼키듯 말한다.",tap:["예.","산길은 아직 내 눈에 있사옵니다.","말씀하소서."],obey:["산길은 놓지 않았사옵니다. 맡겨 주소서.","이 몸이 앞서 길을 보이겠사옵니다.","그리하겠사옵니다."],auto:["산은 아직 내 것이옵니다! 이 싸움은 내가 맡겠사옵니다!","고개를 막아라! 한 놈도 넘기지 마라!","길을 지켜라! 다시는 잃지 않는다!","길을 지켰사옵니다.","또 잃었사옵니다. 그래도 산길은 남았사옵니다."],art:["ambush","고개를 막고 숨어라! 넘어오는 자를 한꺼번에 쳐라!"],recorded:!0,male:!0},"maek-1":{voice:"Despina",style:"스물넷의 대담하고 장난기 있는 밤 사냥꾼. 맑고 요염한 목소리로, 웃음을 섞어 말한다.",tap:["<laugh> 부르셨사옵니까.","냄새가 나옵니다.","재미있는 일이옵니까."],obey:["재미만 있다면 하겠사옵니다.","<laugh> 냄새를 따라가 보겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","냄새가 나옵니다! 숨어서 덮쳐라!","밤이 우리 편이다! 달려들어라!","<laugh> 재미있었사옵니다. 이겼사옵니다.","재미없게 되었사옵니다. 물러나옵니다."],art:["ambush","밤이 깊었다! 냄새를 따라 어둠에서 덮쳐라!"],recorded:!0},"maga-1":{voice:"Rami",style:"마흔둘의 호쾌하고 거침없는 기병. 시원하고 힘찬 사내의 목소리로, 말을 몰듯 말한다.",tap:["예! 말씀하소서.","말은 바람 같사옵니다.","부르셨사옵니까."],obey:["길만 정해 주소서. 바람처럼 가겠사옵니다.","말이 닿는 곳이면 어디든 가겠사옵니다.","맡겨 주소서!"],auto:["이 싸움은 제가 맡겠사옵니다!","말을 몰아라! 바람처럼 휩쓸어라!","멈추지 마라! 달리며 베어라!","바람이 우리 편이었사옵니다.","바람이 멎었사옵니다. 다시 달리겠사옵니다."],art:["vanguard","길은 정해졌다! 말을 몰아 바람처럼 돌파하라!"],recorded:!0,male:!0},"maga-ruler":{voice:"Laomedeia",style:"스물일곱의 시원하고 호방한 마가의 딸. 맑고 청량한 목소리로, 말 위에서 자란 기운이 묻어나게 시원시원 말한다.",tap:["예, 여기 있사옵니다.","말은 매어 두었사옵니다.","말씀하소서."],obey:["말 달리듯 해내겠사옵니다.","충심을 다하겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","말을 달려라! 달리며 쏘아라!","흩어지지 마라! 바람처럼 가자!","이겼사옵니다. 말에게 물을 먹이겠사옵니다.","송구하옵니다. 다시 말을 몰겠사옵니다."],art:["snipe","달리며 겨누어라! 마가의 활이 적장을 노린다!"],recorded:!0},"mh-mahan-1":{voice:"Brio",style:"마흔여섯의 우직하고 힘센 사내. 짧고 묵직한 목소리로, 큰 돌처럼 말수 적게 말한다.",tap:["예.","여기 있사옵니다.","말씀하소서."],obey:["맡겨 주소서.","돌처럼 버티겠사옵니다.","힘쓰는 일이라면 제가 하겠사옵니다."],auto:["제가 맡겠사옵니다!","돌을 굴려라! 밀고 나가라!","물러서지 마라! 바위처럼 서라!","끝났사옵니다.","무너졌사옵니다. 다시 쌓겠사옵니다."],art:["vanguard","큰 돌이 굴러간다! 비켜서지 않으면 짓밟는다!"],recorded:!0,male:!0},"mh-mahan-3":{voice:"Zeno",style:"마흔여덟의 고집 세고 의심 많은 사내. 퉁명스럽고 묵직한 목소리로 말한다.",tap:["예.","왜 부르셨사옵니까.","무슨 일이옵니까."],obey:["믿어도 되는 일인지 보고 하겠사옵니다.","한번 믿으면 끝까지 가겠사옵니다.","그리하겠사옵니다."],auto:["정 그러시다면 제가 맡겠사옵니다!","의심은 접어라! 한번 믿었으면 끝까지 간다!","바위처럼 서라! 물러서지 마라!","믿은 보람이 있었사옵니다.","믿은 내가 어리석었사옵니다. 다시 보겠사옵니다."],art:["order","바위처럼 서라! 의심은 접고 대열을 지켜라!"],recorded:!0,male:!0},"michuhol-1":{voice:"Gero",style:"쉰 살의 억척스럽고 묵묵한 뱃길 일꾼. 투박한 중년 사내의 목소리로, 셈이 밝은 듯 담담히 말한다.",tap:["예, 짐 내려놓고 왔사옵니다.","무슨 일이옵니까.","말씀하소서."],obey:["한 짐 더 지겠사옵니다.","셈은 제가 틀리지 않사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","짐을 지듯 버텨라! 한 걸음씩 나아가라!","뱃길을 막아라! 지나가지 못하게!","짐이 가벼워졌사옵니다. 이겼사옵니다.","짐이 무거웠사옵니다. 다시 지겠사옵니다."],art:["ambush","소금 가마 뒤에 숨어라! 짐 내리는 척하다 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"michuhol-2":{voice:"Lora",style:"스물셋의 약삭빠르고 대담한 갯가 장사치. 맑고 능청스러운 목소리로, 제 몫부터 챙기듯 말한다.",tap:["예, 부르셨사옵니까.","제 몫은 따로이옵니다.","무슨 이문이 있사옵니까."],obey:["제 몫만 챙겨 주시면 하겠사옵니다.","밤이면 더 잘하옵니다.","맡겨 주소서."],auto:["이 싸움도 제가 맡겠사옵니다!","어둠을 타라! 한 놈씩 홀리듯 끌어내라!","소리 없이 치고 빠져라!","챙겼사옵니다. 이겼사옵니다.","밑졌사옵니다. 다음엔 제 몫을 먼저 챙기겠사옵니다."],art:["ambush","밤 물건처럼 소리 없이! 어둠 속에서 치고 빠져라!"],recorded:!0},"miri-1":{voice:"Puck",style:"마흔여섯의 넉살 좋은 술꾼 이야기꾼. 반쯤 취한 듯 가락 있는 중년 사내의 목소리로, 허허 웃으며 말한다.",shoutStyle:"마흔여섯의 이야기꾼. 가락 있는 중년 사내의 목소리지만 싸움에서는 취기 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["허허, 왔사옵니다.","한 잔 받으시지요.","옛 싸움 이야기 하나 해 드릴까요."],obey:["한 잔만 걸치고 하겠사옵니다.","허허, 맡겨 주소서.","옛날엔 이보다 더한 일도 했사옵니다."],auto:["허허, 이 싸움은 제가 맡겠사옵니다!","취한 놈이 제일 겁이 없다! 밀어붙여라!","한 잔 마신 셈 치고 덤벼라!","허허, 이겼으니 한 잔 받으시지요.","허허, 졌사옵니다. 이것도 술안주가 되옵니다."],art:["feint","취한 척 물러서라! 쫓아오면 그때 정신 차려 쳐라!"],recorded:!0,male:!0},"mokji-1":{voice:"Neno",style:"예순둘의 노련하고 푸근한 늙은 장수. 느릿하고 정겨운 노인의 목소리로, 웃으면서도 물러서지 않는 뚝심이 묻어난다.",tap:["허허, 군사는 세워 두었사옵니다.","말씀하소서.","부르셨사옵니까."],obey:["허허, 평생 해 온 일이옵니다.","맡겨 주소서. 천천히 틀림없이 하겠사옵니다.","그리하겠사옵니다."],auto:["허허, 이 늙은이가 맡겠사옵니다!","진을 세워라! 평생 세워 온 진이다!","서두르지 마라! 한 줄씩 나아가라!","허허, 이겼사옵니다. 다들 수고했소.","허허, 졌사옵니다. 그래도 진은 무너지지 않았사옵니다."],art:["order","진을 세워라! 평생 세워 온 진이다, 한 발도 어긋나지 마라!"],recorded:!0,male:!0},"mujin-1":{voice:"Elio",style:"서른넷의 귀티 나고 차분한 이름난 집 사람. 단정하고 품위 있는 사내의 목소리로 말한다.",tap:["부르셨사옵니까.","말씀하소서.","예, 듣고 있사옵니다."],obey:["집안의 이름에 걸맞게 하겠사옵니다.","차분히 해내겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","품위를 잃지 마라! 대열을 지켜라!","흐트러지지 마라! 한 줄로 나아가라!","이겼사옵니다. 당연한 결과이옵니다.","송구하옵니다. 집안의 이름에 누가 되었사옵니다."],art:["order","품위를 잃지 마라! 흐트러짐 없이 한 줄로 나아간다!"],recorded:!0,male:!0},"sabeol-ruler":{voice:"Cruz",style:"쉰다섯의 강직하고 노련한 늙은 장수. 무겁고 짧은 사내의 목소리로, 눈빛으로 군사를 세우듯 말한다.",tap:["예.","말씀하소서.","준비되어 있사옵니다."],obey:["맡기소서.","한 번 말씀하시면 되옵니다.","그리하겠사옵니다."],auto:["제가 맡겠사옵니다!","눈을 떼지 마라! 신호를 기다려라!","흩어지지 마라! 따라와라!","끝났사옵니다.","물러나옵니다. 다시 세우겠사옵니다."],art:["ambush","말없이 엎드려라! 내 눈짓에 한꺼번에 일어나 덮쳐라!"],recorded:!0,male:!0},"samul-ruler":{voice:"Sadachbia",style:"서른넷의 거침없고 호기로운 뱃사람. 시원하게 내지르는 힘찬 사내의 목소리로 말한다.",shoutStyle:"서른넷의 뱃사람. 시원한 사내의 목소리지만 싸움에서는 장난기 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예! 부르셨사옵니까.","바람이 좋사옵니다!","돛은 올려 두었사옵니다."],obey:["바람을 타고 다녀오겠사옵니다!","돛만 올리면 어디든 가옵니다.","맡겨 주소서!"],auto:["바람이 우리 편이다! 제가 맡겠사옵니다!","돛을 올려라! 앞으로 내질러라!","기세다! 기세로 밀어라!","이겼사옵니다! 바람이 도왔사옵니다.","바람이 돌았사옵니다. 다시 돛을 올리겠사옵니다."],art:["ambush","돛을 내리고 곶 뒤에 숨어라! 바람이 불면 뛰쳐나가 들이쳐라!"],recorded:!0,male:!0},"sangdang-1":{voice:"Schedar",style:"마흔둘의 무뚝뚝하고 힘센 대장장이. 투박하고 짧은 사내의 목소리로, 웃기보다 두드리듯 말한다.",tap:["예.","망치는 들고 있사옵니다.","말씀하소서."],obey:["두들겨 놓겠사옵니다.","맡겨 주소서.","날이 서도록 하겠사옵니다."],auto:["망치가 맡겠사옵니다!","두들겨라! 앞을 펴 버려라!","밀어붙여라! 한 번에 내리쳐라!","잘 두들겼사옵니다.","날이 나가 버렸사옵니다. 다시 달구겠사옵니다."],art:["vanguard","망치를 들어라! 내리쳐서 길을 연다!"],recorded:!0,male:!0},"sangdang-ruler":{voice:"Sadaltager",style:"쉰 살의 깐깐하고 무뚝뚝한 장인. 담담하고 퉁명스러운 사내의 목소리로, 날을 살피며 말한다.",tap:["흠. 말씀하소서.","날은 살펴 두었사옵니다.","예."],obey:["날 하나도 허투루 넘기지 않겠사옵니다.","흠, 맡겨 보소서.","제대로 해 놓겠사옵니다."],auto:["제가 맡겠사옵니다!","날을 세워라! 무딘 칼은 버려라!","한 치도 어긋나지 마라! 정확히 가라!","흠, 날이 잘 들었사옵니다.","흠, 날이 무뎠사옵니다. 다시 갈겠사옵니다."],art:["order","날을 맞추어라! 한 치 어긋남 없이 진을 서라!"],recorded:!0,male:!0},"saro-ruler":{voice:"Milo",style:"마흔둘의 너그럽고 재치 있는 임금. 부드럽고 품위 있는 사내의 목소리로, 떡과 잔치에 빗대어 농을 섞는다.",shoutStyle:"마흔둘의 임금. 부드러운 사내의 목소리지만 싸움에서는 농 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["허허, 부르셨사옵니까.","떡 한 조각 하시겠사옵니까.","말씀하소서."],obey:["잔치 준비하듯 해 놓겠사옵니다.","웃으며 맡겠사옵니다.","허허, 맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","잔칫상을 지켜라! 한 놈도 못 들인다!","웃으며 나아가라! 우리가 이긴다!","허허, 이겼사옵니다. 떡을 돌리시지요.","허허, 졌사옵니다. 잔치는 다시 열면 되옵니다."],art:["sway","칼을 거두어라! 잔치에 오라, 우리와 함께 가자!"],recorded:!0,male:!0},"siljik-1":{voice:"Rasalgethi",style:"마흔다섯의 끈기 있고 묵묵한 사내. 투박하고 담담한 목소리로, 되밀려오는 물결처럼 꾸준히 말한다.",tap:["예.","파도는 쉬지 않사옵니다.","말씀하소서."],obey:["지치지 않고 해내겠사옵니다.","밀려가고 또 밀려오겠사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","밀려라! 물러나도 다시 밀려라!","지치지 마라! 한 번 더다!","끝났사옵니다. 물이 빠지듯 물러가옵니다.","밀려났사옵니다. 다시 밀려오겠사옵니다."],art:["ambush","파도 뒤에 숨었다가 되밀려오듯 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"siljik-ruler":{voice:"Tova",style:"마흔둘의 셈 빠르고 노련한 우두머리. 차분하고 담백한 중년 여인의 목소리로, 셈부터 꺼내듯 말한다.",tap:["예, 말씀하소서.","셈은 셈이옵고, 듣고 있사옵니다.","부르셨사옵니까."],obey:["셈은 셈이옵고, 약속은 지키겠사옵니다.","값만큼은 해내겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","셈이 서 있다! 계획대로 나아가라!","밑지는 짓은 하지 마라! 한 번에 끝낸다!","셈이 맞았사옵니다. 이겼사옵니다.","셈이 틀렸사옵니다. 값은 치르겠사옵니다."],art:["order","셈은 끝났다! 흐트러짐 없이 계획대로 나아간다!"],recorded:!0},"sr-guryema":{voice:"Arlo",style:"서른넷의 과묵하고 예민한 밤 사냥꾼. 낮고 차분한 사내의 목소리로, 어둠 속에서 속삭이듯 말한다.",tap:["예.","밤눈은 밝사옵니다.","말씀하소서."],obey:["어둠 속에서 해내겠사옵니다.","먼저 보고 오겠사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","어둠에 숨어라! 소리 내지 마라!","먼저 본 쪽이 이긴다! 숨죽여라!","끝났사옵니다. 어둠으로 돌아가겠사옵니다.","들켰사옵니다. 다시 숨겠사옵니다."],art:["ambush","불을 꺼라! 어둠에서 먼저 보고 먼저 쳐라!"],recorded:!0,male:!0},"sr-jibaekho":{voice:"Bodi",style:"마흔둘의 사납고 자존심 센 산사람. 굵고 짧은 사내의 목소리로, 범을 잡은 손의 기세가 묻어나게 말한다.",tap:["예.","범은 잡아 두었사옵니다.","말씀하소서."],obey:["범 잡듯 해내겠사옵니다.","마을은 제가 지키옵니다.","맡겨 주소서."],auto:["마을은 제가 지키겠사옵니다!","산에서 내려와라! 범처럼 덮쳐라!","한 놈도 마을에 못 들인다!","범 한 마리 잡은 셈이옵니다. 이겼사옵니다.","범도 놓칠 때가 있사옵니다. 다시 가겠사옵니다."],art:["ambush","범을 잡은 손이다! 산에서 내려와 한꺼번에 덮쳐라!"],recorded:!0,male:!0},"sr-jita":{voice:"Mako",style:"쉰 살의 넉살 좋고 셈 빠른 흥정꾼. 싹싹한 사내의 목소리로, 흥정하듯 말한다.",shoutStyle:"쉰 살의 흥정꾼. 싹싹한 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예, 부르셨사옵니까.","남는 장사이옵니다.","무슨 흥정이옵니까."],obey:["남는 장사이옵니다. 하겠사옵니다.","구슬 하나로 쇠 열 덩이를 바꿔 오겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","값을 깎지 마라! 한 번에 밀어붙여라!","밑질 일 없다! 앞으로!","남는 장사였사옵니다. 이겼사옵니다.","밑졌사옵니다. 다음 흥정은 다를 것이옵니다."],art:["sway","흥정하자! 칼을 거두고 우리 쪽에 서라, 값은 후하게 쳐 주마!"],recorded:!0,male:!0},"sr-wae-ruler":{voice:"Rami",style:"서른여덟의 사납고 뻔뻔한 해적 우두머리. 억센 사내의 목소리로, 흐흐 웃으며 말한다.",tap:["흐흐, 불렀사옵니까.","무슨 일이옵니까.","칼은 들고 있사옵니다."],obey:["흐흐, 빼앗는 일이라면 맡겨 주소서.","칼로 해 오겠사옵니다.","몫만 주시면 하겠사옵니다."],auto:["이 싸움은 제가 맡겠사옵니다!","빼앗아라! 있는 대로 쓸어 담아라!","흐흐, 달려들어라! 먼저 베는 놈이 임자다!","흐흐, 이겼사옵니다. 몫은 나눠 주겠사옵니다.","졌사옵니다. 배를 돌려 물러나옵니다."],art:["vanguard","칼을 뽑아라! 먼저 베는 놈이 임자다, 나를 따르라!"],recorded:!0,male:!0},"tamna-ruler":{voice:"Rina",style:"서른의 엄숙하고 신령스러운 섬의 우두머리. 맑고 또렷하며 강단 있는 목소리로, 신탁을 전하듯 느리고 예스럽게 말한다.",tap:["섬의 신들이 이르시기를, 말씀하소서.","부르셨사옵니까.","신들이 지켜보고 계시옵니다."],obey:["신들의 뜻을 받들겠사옵니다.","섬의 신들이 허락하시면 하겠사옵니다.","맡겨 주소서."],auto:["섬의 신들이 이 싸움을 맡으셨사옵니다!","두려워 마라! 신들이 굽어보신다!","섬을 지켜라! 한 걸음도 내주지 마라!","섬의 신들이 도우셨사옵니다.","신들의 뜻이 달랐사옵니다. 다시 여쭙겠사옵니다."],art:["rite","섬의 신들이시여, 굽어보소서! 이 땅을 어지럽힌 자를 물리쳐 주소서!"],recorded:!0},"uga-1":{voice:"Sadaltager",style:"서른셋의 순박하고 우직한 농사꾼. 느릿하고 구수한 목소리로, 소처럼 꾸준히 말한다.",tap:["예, 느려도 왔사옵니다.","무슨 일이옵니까.","말씀하소서."],obey:["느려도 틀림없이 하겠사옵니다.","밀면 멈추지 않사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","천천히 밀어라! 한번 밀면 멈추지 마라!","버텨라! 소처럼 한 걸음씩!","느려도 이겼사옵니다.","느려서 졌사옵니다. 그래도 다시 밀겠사옵니다."],art:["order","소처럼 천천히, 그러나 멈추지 마라! 한 걸음씩 밀고 나아가라!"],recorded:!0,male:!0},"uga-ruler":{voice:"Riko",style:"마흔의 푸근하고 부지런한 우두머리. 정겹고 넉넉한 사내의 목소리로, 허허 웃으며 소와 밭 이야기를 섞는다.",tap:["허허, 밭에서 왔사옵니다.","부르셨사옵니까.","소는 먹여 두었사옵니다."],obey:["허허, 밭 갈듯 해내겠사옵니다.","부지런히 해 놓겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","쟁기 밀듯 나아가라! 힘을 빼지 마라!","곡식이 기다린다! 이기고 돌아가자!","허허, 이겼사옵니다. 소에게 꼴을 먹입시다.","허허, 졌사옵니다. 갈아엎고 다시 하면 되옵니다."],art:["shout","곡식이 기다린다! 쟁기 밀듯 힘을 모아 함성을 올려라!"],recorded:!0,male:!0},"ungcheon-ruler":{voice:"Umbriel",style:"서른다섯의 느긋하지만 뚝심 있는 사내. 후덕하고 굵은 목소리로, 곰나루 사람답게 웃으며 말한다.",tap:["곰나루 사람이옵니다. 말씀하소서.","허허, 왔사옵니다.","부르셨사옵니까."],obey:["곰나루 사람은 믿으면 끝까지 가옵니다.","허허, 맡겨 주소서.","느긋해도 틀림없이 하겠사옵니다."],auto:["곰나루 사람이 맡겠사옵니다!","곰처럼 버텨라! 한 발도 물러서지 마라!","믿는다! 믿고 앞으로!","허허, 이겼사옵니다. 꿀이라도 먹읍시다.","허허, 졌사옵니다. 곰도 겨울잠을 자야 하옵니다."],art:["ambush","숲에서 곰처럼 일어나라! 큰 팔로 한꺼번에 쓸어라!"],recorded:!0,male:!0},"us-1":{voice:"Olin",style:"열여덟의 순박하고 겁 많은 젊은 농사꾼. 맑고 가는 소년의 목소리로, 조금 떨리듯 공손하게 말한다.",tap:["예, 예. 부르셨사옵니까.","밭은 다 매 놓았사옵니다.","무슨 일이옵니까."],obey:["무섭지만 해 보겠사옵니다.","맡은 일은 끝까지 하겠사옵니다.","시키시는 대로 하겠사옵니다."],auto:["제가 맡겠사옵니다! 무서워도 하겠사옵니다!","무서워도 물러서지 마라! 우리 밭이다!","힘을 내라! 지켜야 한다!","이겼사옵니다! 다들 무사하시옵니까.","죄송하옵니다. 다음엔 더 잘하겠사옵니다."],art:["shout","우리 밭이다! 무서워도 지켜야 한다, 함성을 올려라!"],recorded:!0,male:!0},"usan-ruler":{voice:"Algenib",style:"마흔여섯의 호탕하고 통 큰 바다의 옛 왕. 우렁찬 사내의 목소리로, 하하하 웃으며 자존심을 감추듯 말한다.",shoutStyle:"마흔여섯의 호탕한 뱃사람. 우렁찬 사내의 목소리지만 싸움에서는 웃음 없이 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["하하하, 왔사옵니다.","부르셨사옵니까.","무슨 일이시옵니까."],obey:["하하하, 맡겨 주소서.","바다의 왕이 직접 하겠사옵니다.","통 크게 해내겠사옵니다."],auto:["하하하, 이 싸움은 제가 맡겠사옵니다!","노를 저어라! 파도를 부숴라!","크게 가라! 통 크게 밀어붙여라!","하하하, 이겼사옵니다! 잔을 채우시오.","하하하, 졌사옵니다. 파도는 또 오는 법이옵니다."],art:["ambush","큰 파도에 섞여라! 한꺼번에 솟구쳐 뱃전을 들이쳐라!"],recorded:!0,male:!0},"usisan-1":{voice:"Enzo",style:"쉰여섯의 푸근하고 고집 센 늙은 대장장이. 느긋하고 정겨운 어른의 목소리로, 웃음을 섞어 쇠와 불에 빗대어 말한다.",tap:["허허, 쇳물 보다 왔사옵니다.","부르셨사옵니까.","말씀하소서."],obey:["허허, 식은 쇠도 다시 달구면 되옵니다.","이 손으로 벼려 보겠사옵니다.","맡겨 주소서."],auto:["허허, 이 대장장이가 맡겠사옵니다!","쇠가 달았다! 지금 두들겨라!","불을 꺼뜨리지 마라! 밀어붙여라!","허허, 잘 벼려졌사옵니다.","허허, 쇠가 식었사옵니다. 다시 달구겠사옵니다."],art:["order","풀무를 밟아라! 쇠처럼 단단하게 진을 굳혀라!"],recorded:!0,male:!0},"usisan-ruler":{voice:"Veda",style:"서른여섯의 듬직하고 실속 있는 포구 마을 우두머리. 넉넉하고 차분한 중년 여인의 목소리로, 느긋하게 말한다.",tap:["예, 말씀하소서.","셈이 맞사옵니다.","부르셨사옵니까."],obey:["셈이 맞는다면 하겠사옵니다.","손해 볼 일은 아니옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","대열을 지켜라! 한 걸음도 밑지지 마라!","버텨라! 우리 몫을 지켜라!","셈이 맞았사옵니다. 이겼사옵니다.","셈이 틀어졌사옵니다. 다시 따져 보겠사옵니다."],art:["order","밑지는 싸움은 없다! 대열을 지켜 한 걸음씩 밀어라!"],recorded:!0},"wander-11":{voice:"Varo",style:"서른여덟의 먹성 좋고 호쾌한 장사. 투박하고 힘찬 사내의 목소리로, 늘 먹는 이야기를 섞어 말한다.",shoutStyle:"서른여덟의 장사. 투박하고 힘찬 사내의 목소리지만 싸움에서는 웃음 없이 짧고 세게 외친다. 말끝을 늘이지 않는다.",tap:["예, 밥부터 먹고 왔사옵니다.","무슨 일이옵니까.","고기는 있사옵니까."],obey:["밥부터 먹고 부수겠사옵니다.","배만 부르면 무엇이든 하옵니다.","맡겨 주소서!"],auto:["배가 찼사옵니다! 제가 맡겠사옵니다!","밥값 하자! 앞을 부숴라!","밀어붙여라! 한 놈도 남기지 마라!","이겼사옵니다. 이제 밥 먹으러 가시지요.","배가 고파서 졌사옵니다. 밥부터 먹겠사옵니다."],art:["vanguard","바위도 부순다! 밥값 하러 앞서 간다, 따라와라!"],recorded:!0,male:!0},"wander-12":{voice:"Ludo",style:"서른셋의 묵묵하고 성실한 떠돌이 대장장이. 담담한 사내의 목소리로 차분하게 말한다.",tap:["예.","망치는 챙겨 왔사옵니다.","말씀하소서."],obey:["성실히 해내겠사옵니다.","머물 곳만 있으면 열심히 하겠사옵니다.","맡겨 주소서."],auto:["제가 맡겠사옵니다!","두드려라! 한 번에 하나씩 쌓아라!","흔들리지 마라! 묵묵히 나아가라!","이겼사옵니다. 머물 곳이 생겼사옵니다.","졌사옵니다. 망치를 다시 들겠사옵니다."],art:["order","망치질하듯 박자를 맞춰라! 한 번에 하나씩 밀고 나간다!"],recorded:!0,male:!0},"wander-19":{voice:"Algieba",style:"쉰넷의 신들린 듯 고고하고 외곬인 점쟁이 궁수. 느리고 읊조리는 어른의 목소리로, 하늘에 묻고 쏘듯 말한다.",tap:["하늘이 이르기를, 말씀하소서.","하늘에 묻고 왔사옵니다.","부르셨사옵니까."],obey:["하늘이 허락하시면 하겠사옵니다.","하늘에 묻고 쏘겠사옵니다.","그리하겠사옵니다."],auto:["하늘이 이 싸움을 맡기셨사옵니다!","하늘에 묻고 쏘아라! 빗나가지 않는다!","숨을 멈춰라! 하늘이 겨누신다!","하늘이 이르신 대로 되었사옵니다.","하늘이 침묵하셨사옵니다. 다시 여쭙겠사옵니다."],art:["snipe","하늘에 묻고 쏜다! 점지된 적장의 이마를 꿰뚫어라!"],recorded:!0,male:!0},"wander-24":{voice:"Varo",style:"서른의 우직하고 호승심 강한 사내. 힘차고 투박한 목소리로, 한번 정하면 놓지 않듯 말한다.",tap:["예.","여기 있사옵니다.","말씀하소서."],obey:["한번 붙잡으면 놓지 않겠사옵니다.","맡겨 주소서. 끝까지 가겠사옵니다.","그리하겠사옵니다."],auto:["제가 맡겠사옵니다!","붙잡아라! 놓지 마라!","버금이라 불린 설움을 이번엔 갚는다! 앞으로!","이겼사옵니다. 이제 으뜸이옵니다.","또 뒤처졌사옵니다. 다시 붙겠사옵니다."],art:["vanguard","한번 물면 놓지 않는다! 내가 먼저 부딪친다, 따라와라!"],recorded:!0,male:!0},"wansan-ruler":{voice:"Olin",style:"스물셋의 온화하고 시인 기질이 있는 젊은이. 곱고 부드러운 청년의 목소리로, 물이 흐르듯 말한다.",shoutStyle:"스물셋의 온화한 젊은이. 곱고 맑은 청년의 목소리지만 싸움에서는 힘차고 짧게 외친다. 말끝을 늘이지 않는다.",tap:["예, 부르셨사옵니까.","물소리가 곱사옵니다.","말씀하소서."],obey:["물 흐르듯 해내겠사옵니다.","다투지 않고 풀어 보겠사옵니다.","맡겨 주소서."],auto:["이 싸움은 제가 맡겠사옵니다!","물처럼 스며들어라! 막히면 돌아라!","서두르지 마라! 흐름을 타라!","이겼사옵니다. 물소리가 맑사옵니다.","송구하옵니다. 물길을 다시 읽겠사옵니다."],art:["ambush","물처럼 스며들어라! 물안개 속에서 일어나 뒤를 쳐라!"],recorded:!0,male:!0},"yangmaek-ruler":{voice:"Schedar",style:"마흔일곱의 과묵하고 자존심 강한 산골 나라의 군장. 짧고 무뚝뚝한 사내의 목소리로 말한다.",tap:["예.","말씀하소서.","활은 아무에게나 내주지 않사옵니다."],obey:["활을 쥘 자격이 있는지 보여 드리겠사옵니다.","받들겠사옵니다.","그리하겠사옵니다."],auto:["제 활이 맡겠사옵니다!","맥궁을 당겨라! 한 발도 헛되이 쏘지 마라!","산골의 활이다! 물러서지 마라!","끝났사옵니다. 활을 거두겠사옵니다.","활이 모자랐사옵니다. 다시 깎겠사옵니다."],art:["snipe","맥궁이 운다! 산골의 한 발로 적장을 꿰뚫어라!"],recorded:!0,male:!0}};export{e as BASE_STYLE,o as FEM_LEAD,r as FEM_STYLE,y as HERO_VOICE,t as HERO_VOICE_1,a as SHOUT_STYLE,d as heroVoiceDir,l as heroVoiceId};
